public with sharing class ContactTriggerHandler {

    /**
     * Before insert/update: copies BillingCountry into MailingCountry (when blank)
     * and, on insert only, AccountSource into LeadSource (when blank) for every
     * contact that has an AccountId.
     *
     * Bulk-safe: a single SOQL query for all referenced accounts, no DML
     * (contact field changes are persisted by the before-trigger save order).
     */
    public static void populateFromAccount(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: when an account has no Phone, copies the Phone of the first
     * qualifying contact (in trigger order) onto the account.
     *
     * Bulk-safe: one SOQL query and at most one DML statement. Iterating
     * Trigger.new in order and marking the account phone as soon as it is set
     * guarantees that, for several new contacts of the same account, the first
     * contact with a phone wins — exactly like the original per-row logic.
     */
    public static void syncAccountPhone(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            // Only the first contact (in trigger order) sets the account phone:
            // once a.Phone is populated here, later contacts of the same account
            // are skipped, mirroring the original loop's re-query behaviour.
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
