public inherited sharing class ExchangeRateClient {

    private static final String NAMED_CREDENTIAL_URL = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer MAX_ATTEMPTS = 2;

    public class ExchangeRateException extends Exception {}

    /**
     * Fetches live FX rates for the given quote currencies against the given base currency.
     *
     * @param baseCurrency     the base currency code (will be trimmed and upper-cased)
     * @param quoteCurrencies  the quote currency codes (will be trimmed and upper-cased)
     * @return a map from every requested (normalised) currency code to its rate
     * @throws ExchangeRateException if inputs are invalid, the callout ultimately fails,
     *         a requested rate is missing, or the response body cannot be parsed
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- Normalise and validate input before making any callout ----
        String base = normalise(baseCurrency);
        if (!isValidCode(base)) {
            throw new ExchangeRateException('Invalid base currency code: '
                + String.valueOf(baseCurrency));
        }

        // Null or empty quote set -> fail fast without a callout.
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency must be provided.');
        }

        List<String> quotes = new List<String>();
        for (String raw : quoteCurrencies) {
            String code = normalise(raw);
            if (!isValidCode(code)) {
                throw new ExchangeRateException('Invalid quote currency code: '
                    + String.valueOf(raw));
            }
            quotes.add(code);
        }

        // ---- Build the request ----
        HttpRequest request = buildRequest(base, quotes);

        // ---- Execute with a single retry on 503 ----
        HttpResponse response;
        for (Integer attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            response = send(request);
            if (response.getStatusCode() != 503) {
                break;
            }
            // 503: retry once with an identical request. If this was the last
            // attempt, the loop exits and the status is validated below.
        }

        Integer status = response.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Exchange rate request failed with status '
                + status);
        }

        // ---- Parse the response body ----
        RatesResponse parsed;
        try {
            parsed = (RatesResponse) JSON.deserialize(response.getBody(), RatesResponse.class);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response body: '
                + e.getMessage());
        }

        Map<String, Decimal> rates = parsed == null ? null : parsed.rates;
        if (rates == null) {
            throw new ExchangeRateException('Exchange rate response does not contain rates.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Decimal rate = rates.get(code);
            if (rate == null) {
                throw new ExchangeRateException('No rate returned for currency ' + code);
            }
            result.put(code, rate);
        }
        return result;
    }

    private static HttpResponse send(HttpRequest request) {
        try {
            return new Http().send(request);
        } catch (System.CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }
    }

    private static HttpRequest buildRequest(String base, List<String> quotes) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(NAMED_CREDENTIAL_URL
            + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(String.join(quotes, ','), 'UTF-8'));
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(60000);
        return request;
    }

    private static String normalise(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        return code != null && code.length() == 3 && code.matches('[A-Z]{3}');
    }

    @SuppressWarnings('PMD.UnusedLocalVariable')
    private class RatesResponse {
        public String base;
        public String date;
        public Map<String, Decimal> rates;
    }
}
