/**
 * Domain service that groups Contacts of the given Accounts by the domain part
 * of their email address (lower-cased).
 *
 * - Runs with sharing enforced (respects the running user's record access).
 * - Bulk-safe: single SOQL query for all incoming ids.
 * - Contacts without an email (null or blank) are excluded.
 * - A null or empty input set returns an empty map.
 */
public inherited sharing class ContactDomainService {

    private static final String AT = '@';

    /**
     * Groups contacts belonging to the given accounts by the (lower-cased)
     * domain part of their email address.
     *
     * @param accountIds  set of Account ids; may be null or empty
     * @return map of lower-cased email domain -> list of Contacts
     *         (each Contact has Id, Email and AccountId populated)
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        // Null or empty input -> empty map
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Single bulkified query; sharing is enforced by 'inherited sharing'
        // in combination with the with-user context (no stripInaccessible needed
        // because only Id, Email and AccountId are read and returned).
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            ORDER BY Id
        ];

        for (Contact con : contacts) {
            String email = con.Email;
            if (email == null) {
                continue;
            }
            email = email.trim();
            if (email.isEmpty()) {
                continue;
            }

            String domain = extractDomain(email);
            if (domain == null) {
                continue;
            }

            List<Contact> bucket = result.get(domain);
            if (bucket == null) {
                bucket = new List<Contact>();
                result.put(domain, bucket);
            }
            bucket.add(con);
        }

        return result;
    }

    /**
     * Extracts the domain part of an email address (text after the last '@'),
     * lower-cased. Returns null if the email contains no '@' or the domain
     * part is empty.
     */
    private static String extractDomain(String email) {
        Integer atIndex = email.lastIndexOf(AT);
        if (atIndex < 0 || atIndex == email.length() - 1) {
            return null;
        }
        return email.substring(atIndex + 1).toLowerCase();
    }
}
