public with sharing class RecordSearchService {

    /**
     * Thrown for every invalid input, metadata/permission problem, or query
     * failure raised by RecordSearchService.search.
     */
    public class SearchException extends Exception {}

    private static final Integer MAX_ROWS_UPPER_BOUND = 200;

    /**
     * Runs a single dynamic SOQL query against any object with simple equality
     * filters, enforcing CRUD/FLS and sharing of the running user.
     *
     * @param objectApiName API name of the object to query (case-insensitive).
     * @param fields        API names of fields to select in addition to Id (case-insensitive).
     * @param filters       Map of field API name -> equality value (values are bound, never concatenated).
     * @param orderByField  Optional field API name to sort ascending by (case-insensitive).
     * @param maxRows       Row limit, must be between 1 and 200.
     * @throws SearchException for every validation or permission failure.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        validateMaxRows(maxRows);
        validateFieldsParameter(fields);

        Schema.DescribeSObjectResult objectDescribe = resolveObject(objectApiName);
        if (objectDescribe == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }
        if (!objectDescribe.isAccessible()) {
            throw new SearchException(
                'The running user cannot read the object "' + objectDescribe.getName() + '".'
            );
        }

        // Field API names below are taken verbatim from the describe layer,
        // which is the injection-safe, correctly-cased source of truth.
        List<String> selectFields = buildSelectFields(objectDescribe, fields);

        String query = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objectDescribe.getName();

        // Filter values are passed as bind variables via queryWithBinds,
        // so they can never alter the structure of the query.
        Map<String, Object> bindVariables = new Map<String, Object>();
        String whereClause = buildWhereClause(objectDescribe, filters, bindVariables);
        if (whereClause != null) {
            query += ' WHERE ' + whereClause;
        }

        String orderByClause = buildOrderByClause(objectDescribe, orderByField);
        if (orderByClause != null) {
            query += ' ' + orderByClause;
        }

        // maxRows is a validated Integer (1..200), so direct embedding is safe.
        query += ' LIMIT ' + maxRows;

        try {
            // USER_MODE enforces object CRUD, field-level security (FLS) and
            // record sharing of the running user at query execution time.
            return Database.queryWithBinds(query, bindVariables, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('The search query could not be executed: ' + e.getMessage());
        }
    }

    private static void validateMaxRows(Integer maxRows) {
        if (maxRows == null || maxRows < 1 || maxRows > MAX_ROWS_UPPER_BOUND) {
            throw new SearchException(
                'maxRows must not be null and must be between 1 and ' + MAX_ROWS_UPPER_BOUND + '.'
            );
        }
    }

    private static void validateFieldsParameter(List<String> fields) {
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }
    }

    /**
     * Resolves an object API name (case-insensitively) to its describe result,
     * or returns null when the object does not exist.
     */
    private static Schema.DescribeSObjectResult resolveObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            return null;
        }
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sobjectType = globalDescribe.get(objectApiName);
        if (sobjectType == null) {
            // Defensive fallback: global describe keys are lowercase.
            for (String key : globalDescribe.keySet()) {
                if (key.equalsIgnoreCase(objectApiName)) {
                    sobjectType = globalDescribe.get(key);
                    break;
                }
            }
        }
        return sobjectType == null ? null : sobjectType.getDescribe();
    }

    /**
     * Resolves a field API name (case-insensitively) on the given object,
     * or returns null when the field does not exist.
     */
    private static Schema.SObjectField resolveField(Schema.DescribeSObjectResult objectDescribe, String fieldApiName) {
        if (String.isBlank(fieldApiName)) {
            return null;
        }
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldApiName);
        if (field != null) {
            return field;
        }
        // Defensive fallback: field map keys are lowercase.
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }

    /**
     * Builds the SELECT list ('Id' plus the requested fields, deduplicated),
     * validating that every requested field exists and is readable.
     */
    private static List<String> buildSelectFields(Schema.DescribeSObjectResult objectDescribe, List<String> fields) {
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seenFields = new Set<String>{ 'Id' };

        for (String fieldApiName : fields) {
            Schema.SObjectField field = resolveField(objectDescribe, fieldApiName);
            if (field == null) {
                throw new SearchException(
                    'Field "' + fieldApiName + '" is not a field of "' + objectDescribe.getName() + '".'
                );
            }
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException(
                    'The running user cannot read the field "' + fieldDescribe.getName() + '" on "' +
                    objectDescribe.getName() + '".'
                );
            }
            String canonicalName = fieldDescribe.getName();
            if (!seenFields.contains(canonicalName)) {
                seenFields.add(canonicalName);
                selectFields.add(canonicalName);
            }
        }
        return selectFields;
    }

    /**
     * Builds the WHERE clause of `field = :bind` conditions joined with AND,
     * or null when there are no filters. Validates that every filter field
     * exists, is readable and is filterable.
     */
    private static String buildWhereClause(
        Schema.DescribeSObjectResult objectDescribe,
        Map<String, Object> filters,
        Map<String, Object> bindVariables
    ) {
        if (filters == null || filters.isEmpty()) {
            return null;
        }

        List<String> conditions = new List<String>();
        Integer bindIndex = 0;

        for (String filterFieldApiName : filters.keySet()) {
            Schema.SObjectField field = resolveField(objectDescribe, filterFieldApiName);
            if (field == null) {
                throw new SearchException(
                    'Filter field "' + filterFieldApiName + '" is not a field of "' +
                    objectDescribe.getName() + '".'
                );
            }
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException(
                    'The running user cannot read the filter field "' + fieldDescribe.getName() + '" on "' +
                    objectDescribe.getName() + '".'
                );
            }
            if (!fieldDescribe.isFilterable()) {
                throw new SearchException(
                    'The field "' + fieldDescribe.getName() + '" cannot be used to filter "' +
                    objectDescribe.getName() + '" records.'
                );
            }

            String bindKey = 'filterValue' + bindIndex;
            conditions.add(fieldDescribe.getName() + ' = :' + bindKey);
            bindVariables.put(bindKey, filters.get(filterFieldApiName));
            bindIndex++;
        }

        return String.join(conditions, ' AND ');
    }

    /**
     * Builds the ORDER BY clause (ascending), or null when orderByField is
     * blank. Validates that the field exists, is readable and is sortable.
     */
    private static String buildOrderByClause(Schema.DescribeSObjectResult objectDescribe, String orderByField) {
        if (String.isBlank(orderByField)) {
            return null;
        }

        Schema.SObjectField field = resolveField(objectDescribe, orderByField);
        if (field == null) {
            throw new SearchException(
                'Order-by field "' + orderByField + '" is not a field of "' + objectDescribe.getName() + '".'
            );
        }
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'The running user cannot read the order-by field "' + fieldDescribe.getName() + '" on "' +
                objectDescribe.getName() + '".'
            );
        }
        if (!fieldDescribe.isSortable()) {
            throw new SearchException(
                'The field "' + fieldDescribe.getName() + '" cannot be used to sort "' +
                objectDescribe.getName() + '" records.'
            );
        }

        return 'ORDER BY ' + fieldDescribe.getName() + ' ASC';
    }
