/**
 * Parses e-commerce order JSON payloads posted to an Apex REST endpoint and
 * produces acknowledgement responses.
 *
 * All parse-level failures are surfaced as OrderPayloadParser.PayloadException
 * so callers never have to handle System.* exceptions from malformed input.
 */
public inherited sharing class OrderPayloadParser {

    /** Raised for any invalid payload (null/blank, bad JSON, bad structure, bad values). */
    public class PayloadException extends Exception {}

    /** A single order line. */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /** A parsed order. */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    /**
     * Parses an order payload.
     *
     * @param body the raw JSON request body
     * @return the parsed Order
     * @throws PayloadException when the body is null/blank, not valid JSON, not a JSON
     *         object, has a missing/blank number, or has a line with a missing sku,
     *         a missing/non-positive quantity, or a missing/negative unitPrice.
     */
    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object rootObj;
        try {
            rootObj = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON.');
        }

        if (!(rootObj instanceof Map<String, Object>)) {
            throw new PayloadException('Request body is not a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) rootObj;

        Order order = new Order();

        // number: required, non-blank string
        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Missing or blank order number.');
        }
        order.orderNumber = (String) numberObj;

        // date: optional, ISO yyyy-MM-dd
        Object dateObj = root.get('date');
        if (dateObj != null) {
            if (!(dateObj instanceof String)) {
                throw new PayloadException('Order date must be a string in yyyy-MM-dd format.');
            }
            order.orderDate = parseIsoDate((String) dateObj);
        }

        // currency: optional
        Object currencyObj = root.get('currency');
        if (currencyObj instanceof String) {
            order.currencyCode = (String) currencyObj;
        }

        // customer: optional; only email is extracted, unknown keys ignored
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Object emailObj = ((Map<String, Object>) customerObj).get('email');
            if (emailObj instanceof String) {
                order.customerEmail = (String) emailObj;
            }
        }

        // lines: empty list when missing or null
        order.lines = new List<Line>();
        Decimal total = 0;

        Object linesObj = root.get('lines');
        if (linesObj instanceof List<Object>) {
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                Line line = new Line();

                // sku: required
                Object skuObj = lineMap.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('Line is missing sku.');
                }
                if (!(skuObj instanceof String)) {
                    throw new PayloadException('Line sku must be a string.');
                }
                line.sku = (String) skuObj;

                // quantity: required, must be a positive number
                Object quantityObj = lineMap.get('quantity');
                if (quantityObj == null) {
                    throw new PayloadException('Line is missing quantity.');
                }
                Decimal quantityDecimal = toDecimal(quantityObj, 'quantity');
                if (quantityDecimal <= 0) {
                    throw new PayloadException('Line quantity must be positive.');
                }
                line.quantity = Integer.valueOf(quantityDecimal.intValue());

                // unitPrice: required, must not be negative
                Object unitPriceObj = lineMap.get('unitPrice');
                if (unitPriceObj == null) {
                    throw new PayloadException('Line is missing unitPrice.');
                }
                line.unitPrice = toDecimal(unitPriceObj, 'unitPrice');
                if (line.unitPrice < 0) {
                    throw new PayloadException('Line unitPrice must not be negative.');
                }

                // discount: optional fraction in [0, 1]; missing/null means 0
                Object discountObj = lineMap.get('discount');
                if (discountObj == null) {
                    line.discount = 0;
                } else {
                    line.discount = toDecimal(discountObj, 'discount');
                    if (line.discount < 0 || line.discount > 1) {
                        throw new PayloadException('Line discount must be between 0 and 1.');
                    }
                }

                // lineTotal: quantity x unitPrice x (1 - discount), 2dp, half up
                line.lineTotal = (line.quantity * line.unitPrice * (1 - line.discount)).setScale(2, System.RoundingMode.ROUND_HALF_UP);
                total += line.lineTotal;

                order.lines.add(line);
            }
        } else if (linesObj != null) {
            throw new PayloadException('Lines must be a JSON array.');
        }

        order.total = total;
        return order;
    }

    /**
     * Builds the acknowledgement JSON for a parsed order: exactly the keys
     * number, status, lineCount and total.
     */
    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total == null ? 0 : order.total);
        return JSON.serialize(ack);
    }

    /** Parses an ISO yyyy-MM-dd string into a Date; throws PayloadException if invalid. */
    private static Date parseIsoDate(String value) {
        if (value.length() != 10 || !value.matches('^\\d{4}-\\d{2}-\\d{2}$')) {
            throw new PayloadException('Order date must be in yyyy-MM-dd format.');
        }
        Integer year = Integer.valueOf(value.substring(0, 4));
        Integer month = Integer.valueOf(value.substring(5, 7));
        Integer day = Integer.valueOf(value.substring(8, 10));
        try {
            return Date.newInstance(year, month, day);
        } catch (Exception e) {
            throw new PayloadException('Order date is not a valid calendar date.');
        }
    }

    /** Safely coerces a deserialized JSON value to Decimal; throws PayloadException if not numeric. */
    private static Decimal toDecimal(Object value, String fieldName) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        throw new PayloadException('Line ' + fieldName + ' must be a number.');
    }
}
