public with sharing class LeadImportService {

    /**
     * Result of a lead import operation.
     * All members are non-null in every outcome.
     */
    public class ImportResult {
        public Integer successCount;                // number of leads inserted
        public List<Id> insertedIds;                // Ids of the inserted leads, in input order
        public Map<Integer, String> errorsByIndex;  // input position (0-based) -> error message

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * Imports leads with per-row error handling.
     *
     * - Every lead that can be inserted is inserted; the method never throws
     *   because some rows failed.
     * - Blank LeadSource values are defaulted to 'Web' before insert.
     * - Duplicate emails within the call (case-insensitive, whitespace-trimmed)
     *   are rejected before DML: the first occurrence is imported normally,
     *   later occurrences get 'Duplicate email in import: <trimmed lowercased email>'.
     *   This holds even if the first occurrence later fails in the database.
     * - Leads without an email are never treated as duplicates.
     * - Database rejections report all error messages for that row joined with '; '.
     * - Uses a single DML statement per call (Database.insert with allOrNone=false).
     * - Respects the running user's sharing rules (with sharing).
     *
     * @param leads the leads to import; null or empty is allowed
     * @return an ImportResult, never null, with non-null members
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Candidates that will be sent to the database, plus their original indexes.
        List<Lead> candidates = new List<Lead>();
        List<Integer> candidateIndexes = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            // Defensive guard: a null element cannot be inserted.
            if (lead == null) {
                result.errorsByIndex.put(i, 'Invalid lead record: null');
                continue;
            }

            // Duplicate email detection: case-insensitive, trimmed.
            // Null/blank emails are never duplicates.
            String normalizedEmail = lead.Email == null ? null : lead.Email.trim().toLowerCase();
            if (String.isNotBlank(normalizedEmail)) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            // Default LeadSource to Web when blank.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            candidates.add(lead);
            candidateIndexes.add(i);
        }

        if (candidates.isEmpty()) {
            return result;
        }

        // Single DML statement; allOrNone=false allows partial success.
        List<Database.SaveResult> saveResults = Database.insert(candidates, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];
            Integer originalIndex = candidateIndexes[i];

            if (saveResult.isSuccess()) {
                result.insertedIds.add(saveResult.getId());
                result.successCount++;
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : saveResult.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
            }
        }

        return result;
    }
}
