/**
 * Utility to return the active options of any picklist or multi-select picklist
 * field, chosen at runtime, in the order they are defined on the field.
 */
public inherited sharing class PicklistService {

    /**
     * A single selectable option of a picklist field.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Thrown for invalid input, unknown objects/fields or non-picklist fields.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist or multi-select picklist
     * field, in the order they are defined on the field. Object and field API
     * names are case-insensitive and may be standard or custom.
     *
     * @param objectApiName API name of the object (e.g. 'Account' or 'FB_Asset_Check__c')
     * @param fieldApiName  API name of the picklist field (e.g. 'Industry' or 'Status__c')
     * @return list of active options; empty list if the field has no active values
     * @throws PicklistServiceException when a name is null/blank, the object or
     *         field does not exist, or the field is not a picklist/multi-select picklist
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            validateInput(objectApiName, fieldApiName);

            // Resolve the SObjectType (global describe keys are lower-cased, so
            // lower-casing the input makes the lookup case-insensitive).
            Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
            if (sobjType == null) {
                throw new PicklistServiceException(
                    'Object does not exist: ' + objectApiName);
            }

            // Resolve the field on the object (field map keys are lower-cased too).
            Map<String, Schema.SObjectField> fieldMap = sobjType.getDescribe().fields.getMap();
            Schema.SObjectField field = fieldMap.get(fieldApiName.toLowerCase());
            if (field == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectApiName + ': ' + fieldApiName);
            }

            Schema.DescribeFieldResult fieldResult = field.getDescribe();

            // Only picklists and multi-select picklists are supported.
            Schema.DisplayType fieldType = fieldResult.getType();
            if (fieldType != Schema.DisplayType.PICKLIST
                    && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field ' + objectApiName + '.' + fieldApiName
                        + ' is not a picklist or multi-select picklist field.');
            }

            // getPicklistValues() applies to both picklists and multi-select picklists
            // and returns the entries in the order defined on the field.
            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldResult.getPicklistValues()) {
                if (entry.isActive()) {
                    String entryValue = entry.getValue();
                    String entryLabel = entry.getLabel();
                    if (entryLabel == null || entryLabel.isBlank()) {
                        entryLabel = entryValue;
                    }
                    options.add(new Option(entryValue, entryLabel, entry.isDefaultValue()));
                }
            }
            return options;
        } catch (PicklistServiceException e) {
            // Re-throw our own exception untouched.
            throw e;
        } catch (Exception e) {
            // Never leak any other exception type (e.g. NullPointerException).
            throw new PicklistServiceException(
                'Unable to retrieve picklist options for ' + objectApiName + '.'
                    + fieldApiName + ': ' + e.getMessage());
        }
    }

    /**
     * Validates that both API names are provided.
     */
    private static void validateInput(String objectApiName, String fieldApiName) {
        if (objectApiName == null || objectApiName.isBlank()) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (fieldApiName == null || fieldApiName.isBlank()) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }
    }
}
