/**
 * Queueable job that marks accounts as synced to the ERP.
 *
 * Every run is logged by its attached Finalizer (ErpSyncFinalizer), which also
 * handles retrying failed runs (up to 3 attempts total).
 *
 * The finalizer is attached as the very first statement of execute(), before
 * any other work is performed, so that both successful and failed runs are
 * always logged.
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds the accounts to mark as synced to the ERP
     * @param attempt    the attempt number; the first run uses 1
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext ctx) {
        // Attach the finalizer before doing any work so that every run -
        // success or failure - is logged and failed runs are retried.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // All-or-nothing: if any account cannot be saved, the DML statement
        // throws and the exception is deliberately not caught, so the whole
        // transaction (including all of this job's changes) is rolled back
        // and the finalizer records a failure.
        update accounts;
    }
}
