File: force-app/main/default/classes/ErpSyncFinalizer.cls
```apex
/**
 * Transaction Finalizer for ErpAccountSyncJob.
 *
 * Inserts one FB_Job_Log__c record per run:
 *   - Success: Status__c = 'Success'
 *   - Failure: Status__c = 'Failed', Error__c = exception message (max 255 chars),
 *     and, while attempt < 3, a new ErpAccountSyncJob is enqueued for the same
 *     accounts with the attempt incremented by one. After the third failed
 *     attempt nothing more is enqueued.
 */
public with sharing class ErpSyncFinalizer implements Finalizer {

    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer MAX_ERROR_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext ctx) {
        Exception jobException = ctx.getException();
        Boolean failed = jobException != null;

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Status__c = failed ? 'Failed' : 'Success',
            Attempt__c = attempt
        );

        if (failed) {
            String errorMessage = jobException.getMessage();
            if (errorMessage != null && errorMessage.length() > MAX_ERROR_LENGTH) {
                errorMessage = errorMessage.substring(0, MAX_ERROR_LENGTH);
            }
            jobLog.Error__c = errorMessage;
        }

        insert jobLog;

        // Retry the same accounts with the next attempt unless the run
        // succeeded or the third attempt has already failed.
        if (failed && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
