```apex
/**
 * Keeps Account.FB_Open_Pipeline__c (sum of Amount of open Opportunities)
 * and Account.FB_Open_Opportunities__c (count of open Opportunities) up to date.
 *
 * Design notes:
 * - Runs in after context and recomputes totals from the database, so the values
 *   are correct after ANY DML statement, including several DML statements on the
 *   same records within one transaction (Flow followed by Apex, tests, etc.):
 *   each trigger invocation reads the current in-transaction state.
 * - Recomputation is bulk-safe: one aggregate query and one Account update per
 *   invocation, regardless of the number of opportunities (data loads of 200+).
 * - The legacy AccountTrigger copies Rating onto open opportunities on every
 *   Account update. Since this handler updates Accounts, that re-fires
 *   OpportunityTrigger. To prevent an infinite loop, the handler records the
 *   totals it has already written in this transaction and only performs the
 *   Account DML when the recomputed totals actually differ. The chained
 *   Opportunity update (FB_Account_Rating__c only) touches no field that affects
 *   the totals, so it short-circuits and the cycle terminates.
 */
public with sharing class OpportunityPipelineHandler {

    /**
     * Totals already written to an Account during the current transaction,
     * keyed by Account Id. Used both as a recursion guard (with the legacy
     * AccountTrigger) and to avoid pointless DML when nothing changed.
     */
    private static Map<Id, Totals> writtenTotalsByAccountId = new Map<Id, Totals>();

    /** Value object for the two roll-up figures of one Account. */
    private class Totals {
        Decimal pipelineAmount;
        Decimal openCount;

        Totals(Decimal pipelineAmount, Decimal openCount) {
            // Blank amounts count as 0; SUM() of all-null amounts returns null.
            this.pipelineAmount = pipelineAmount == null ? 0 : pipelineAmount;
            this.openCount = openCount == null ? 0 : openCount;
        }

        Boolean sameAs(Totals other) {
            return other != null
                && pipelineAmount == other.pipelineAmount
                && openCount == other.openCount;
        }
    }

    public static void handleInsert(List<Opportunity> newOpportunities) {
        processAccounts(collectAccountIds(newOpportunities));
    }

    public static void handleUpdate(Map<Id, Opportunity> oldMap, Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newOpp : newMap.values()) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            // Totals only depend on these three fields. If none of them changed
            // (e.g. the legacy AccountTrigger only touching FB_Account_Rating__c),
            // there is nothing to do. Otherwise both old and new accounts are
            // affected when the opportunity moved between accounts.
            if (oldOpp.Amount != newOpp.Amount
                || oldOpp.IsClosed != newOpp.IsClosed
                || oldOpp.AccountId != newOpp.AccountId) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        if (!accountIds.isEmpty()) {
            processAccounts(accountIds);
        }
    }

    public static void handleDelete(List<Opportunity> oldOpportunities) {
        processAccounts(collectAccountIds(oldOpportunities));
    }

    public static void handleUndelete(List<Opportunity> newOpportunities) {
        processAccounts(collectAccountIds(newOpportunities));
    }

    /** Collects the non-null AccountIds of the given opportunities. */
    private static Set<Id> collectAccountIds(List<Opportunity> opportunities) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : opportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        return accountIds;
    }

    /**
     * Recomputes the open-pipeline totals for the given accounts from the
     * database (which already reflects all prior DML of this transaction,
     * including the statement that fired the trigger) and updates the accounts
     * whose totals changed. Accounts with no open opportunities get 0 / 0.
     */
    private static void processAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Totals> computedTotals = new Map<Id, Totals>();
        for (AggregateResult result : [
            SELECT AccountId accountIds, SUM(Amount) totalAmount, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountIds');
            computedTotals.put(
                accountId,
                new Totals((Decimal) result.get('totalAmount'), (Decimal) result.get('oppCount'))
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Totals totals = computedTotals.get(accountId);
            if (totals == null) {
                // No open opportunities left on this account: show 0 and 0.
                totals = new Totals(0, 0);
            }
            // Recursion guard / no-op guard: skip accounts whose totals were
            // already written with exactly these values in this transaction.
            if (!totals.sameAs(writtenTotalsByAccountId.get(accountId))) {
                accountsToUpdate.add(new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = totals.pipelineAmount,
                    FB_Open_Opportunities__c = totals.openCount
                ));
                writtenTotalsByAccountId.put(accountId, totals);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
