            buildOpp('Prospecting', 100.555, 50),
            // 200 * 25 / 100 = 50.00
            buildOpp('Negotiation/Review', 200, 25),
            // 0.01 * 50 / 100 = 0.005 -> rounded per opportunity to 0.01 (HALF_UP)
            buildOpp('Qualification', 0.01, 50),
            // 0.01 * 50 / 100 = 0.005 -> rounded per opportunity to 0.01 (HALF_UP)
            buildOpp('Qualification', 0.01, 50)
        };
        // Qualification total must be 0.02 (round-then-sum), not 0.01 (sum-then-round)

