/**
 * Pure unit tests for OpportunityCleanupService.closeStale.
 *
 * No DML and no SOQL is performed: the selector and the unit of work are both
 * mocked with fflib-ApexMocks and injected via the Application factories
 * (Application.Selector.setMock / Application.UnitOfWork.setMock).
 * All record ids are fakes produced by fflib_IDGenerator.
 *
 * Contract pinned down by these tests:
 *  - An opportunity is stale when its StageName is neither 'Closed Won' nor
 *    'Closed Lost' AND its CloseDate is strictly before the cutoff date.
 *    Opportunities closing on the cutoff date (or later), with a null
 *    CloseDate, or already in a closed stage are left untouched.
 *  - Each stale opportunity is mutated to StageName = 'Closed Lost' and
 *    Description = OpportunityCleanupService.LOST_REASON and registered on
 *    the unit of work via registerDirty(SObject). No other opportunity is
 *    registered.
 *  - commitWork() is called exactly once when at least one opportunity was
 *    closed, and never when none was.
 *  - The method returns the number of opportunities closed; null or empty
 *    id sets return 0 without touching the selector or unit of work.
 */
@IsTest
private class OpportunityCleanupServiceTest {

    @IsTest
    static void closesOnlyStaleOpenOpportunities() {
        Date cutoff = Date.today();

        Set<Id> oppIds = new Set<Id>();
        Opportunity staleOpen = stagedOpp('Stale open opp', 'Open', cutoff.addDays(-1), oppIds);
        Opportunity staleReview = stagedOpp('Stale review opp', 'Negotiation/Review', cutoff.addDays(-365), oppIds);
        Opportunity closingOnCutoff = stagedOpp('Closes on cutoff', 'Open', cutoff, oppIds);
        Opportunity closingInFuture = stagedOpp('Closes in future', 'Open', cutoff.addDays(30), oppIds);
        Opportunity nullCloseDate = stagedOpp('Null close date', 'Open', null, oppIds);
        Opportunity alreadyWon = stagedOpp('Already won', 'Closed Won', cutoff.addDays(-1), oppIds);
        Opportunity alreadyLost = stagedOpp('Already lost', 'Closed Lost', cutoff.addDays(-90), oppIds);

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(oppIds)).thenReturn(
            new List<Opportunity>{
                staleOpen,
                staleReview,
                closingOnCutoff,
                closingInFuture,
                nullCloseDate,
                alreadyWon,
                alreadyLost });
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(oppIds, cutoff);
        Test.stopTest();

        // Only the two strictly-before-cutoff, non-closed opportunities count.
        System.assertEquals(2, closed,
            'Exactly the two stale open opportunities should have been closed');

        // The selector was queried with the ids given to the service.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(oppIds);

        // Each stale opportunity is marked Closed Lost with the lost reason
        // and registered dirty exactly once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(
            expectClosed(staleOpen));
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(
            expectClosed(staleReview));

        // No other opportunity is ever registered: not those closing on the
        // cutoff date or later, not the one with a null CloseDate, and not
        // the already-closed ones.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(closingOnCutoff);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(closingInFuture);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(nullCloseDate);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(alreadyWon);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(alreadyLost);

        // Work is committed exactly once because at least one opp was closed.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @IsTest
    static void doesNothingWhenThereAreNoStaleOpportunities() {
        Date cutoff = Date.today();

        Set<Id> oppIds = new Set<Id>();
        Opportunity alreadyWon = stagedOpp('Already won', 'Closed Won', cutoff.addDays(-1), oppIds);
        Opportunity alreadyLost = stagedOpp('Already lost', 'Closed Lost', cutoff.addDays(-1), oppIds);
        Opportunity closingOnCutoff = stagedOpp('Closes on cutoff', 'Qualification', cutoff, oppIds);
        Opportunity closingInFuture = stagedOpp('Closes in future', 'Open', cutoff.addDays(1), oppIds);

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(oppIds)).thenReturn(
            new List<Opportunity>{
                alreadyWon, alreadyLost, closingOnCutoff, closingInFuture });
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(oppIds, cutoff);
        Test.stopTest();

        System.assertEquals(0, closed,
            'No opportunity should have been closed when none is stale');

        // The selector is still consulted for the given ids.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(oppIds);

        // Nothing is registered dirty and commitWork() is never called.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(alreadyWon);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(alreadyLost);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(closingOnCutoff);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(closingInFuture);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void returnsZeroAndDoesNothingWhenIdsAreNull() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(null, Date.today());
        Test.stopTest();

        System.assertEquals(0, closed,
            'A null id set should short-circuit to 0');

        // Neither the selector nor the unit of work is touched.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0)).selectById(new Set<Id>());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(
            new Opportunity(Id = fflib_IDGenerator.generate(Opportunity.SObjectType)));
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void returnsZeroAndDoesNothingWhenIdsAreEmpty() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(new Set<Id>(), Date.today());
        Test.stopTest();

        System.assertEquals(0, closed,
            'An empty id set should short-circuit to 0');

        // Neither the selector nor the unit of work is touched.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0)).selectById(new Set<Id>());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(
            new Opportunity(Id = fflib_IDGenerator.generate(Opportunity.SObjectType)));
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void closesSingleStaleOpportunityAndCommitsOnce() {
        Date cutoff = Date.today();

        Set<Id> oppIds = new Set<Id>();
        Opportunity stale = stagedOpp('Single stale opp', 'Prospecting', cutoff.addDays(-7), oppIds);
        Opportunity won = stagedOpp('Already won', 'Closed Won', cutoff.addDays(-7), oppIds);

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(oppIds)).thenReturn(
            new List<Opportunity>{ stale, won });
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(oppIds, cutoff);
        Test.stopTest();

        System.assertEquals(1, closed,
            'Only the single stale opportunity should have been closed');

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(
            expectClosed(stale));
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(won);

        // Even with exactly one closed opportunity, commitWork() runs once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    /**
     * Builds an in-memory Opportunity with a fake id (no DML) and records
     * the id in the given set so it can be used as the selector input.
     */
    private static Opportunity stagedOpp(String name, String stageName, Date closeDate, Set<Id> ids) {
        Id recordId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        ids.add(recordId);
        return new Opportunity(
            Id = recordId,
            Name = name,
            StageName = stageName,
            CloseDate = closeDate);
    }

    /**
     * The expected state of a stale opportunity after closeStale has processed
     * it: same id, name and close date, stage forced to 'Closed Lost' and the
     * description set to OpportunityCleanupService.LOST_REASON.
     */
    private static Opportunity expectClosed(Opportunity stale) {
        return new Opportunity(
            Id = stale.Id,
            Name = stale.Name,
            StageName = 'Closed Lost',
            CloseDate = stale.CloseDate,
            Description = OpportunityCleanupService.LOST_REASON);
    }
}
