File: force-app/main/default/classes/Opportunities.cls
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    public static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * An opportunity qualifies on insert when it is created directly as Closed Won.
     */
    public override void onAfterInsert(List<SObject> records) {
        startFulfilment(selectNewlyWonIds(records, null));
    }

    /**
     * An opportunity qualifies on update when its stage changes to Closed Won
     * from any other stage. Opportunities that were already Closed Won do not
     * qualify again (their before value is also Closed Won).
     */
    public override void onAfterUpdate(
        List<SObject> records,
        Map<Id, SObject> existingRecords,
        Map<String, Object> changesByFieldName
    ) {
        startFulfilment(selectNewlyWonIds(records, existingRecords));
    }

    /**
     * Returns the ids of the opportunities in this invocation that are now
     * Closed Won and were not Closed Won before (null existingRecords means insert).
     */
    private Set<Id> selectNewlyWonIds(List<SObject> records, Map<Id, SObject> existingRecords) {
        Set<Id> newlyWonIds = new Set<Id>();
        for (SObject sobj : records) {
            Opportunity opp = (Opportunity) sobj;
            Boolean isNowWon = opp.StageName == STAGE_CLOSED_WON;
            Boolean wasNotWon =
                existingRecords == null
                || ((Opportunity) existingRecords.get(opp.Id)).StageName != STAGE_CLOSED_WON;
            if (isNowWon && wasNotWon) {
                newlyWonIds.add(opp.Id);
            }
        }
        return newlyWonIds;
    }

    /**
     * Calls startFulfilment at most once per trigger invocation, with the ids of
     * all qualifying opportunities, and not at all when none qualify. The service
     * is obtained via Application so tests can replace it with Application.Service.setMock.
     */
    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service = (IOpportunityFulfilmentService)
            Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }
}
