    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, fflib_SObjectDomain.Workable workLater)
    {
        super(records, workLater);
    }

    /**
     * Test constructor (library convention) to support domain unit tests.
     */
    public Opportunities(Set<Id> recordIds)
    {
        super(recordIds);
    }

    /**
     * The constructable inner class the library uses to instantiate this
     * domain class from the trigger handler and domain factory.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public Opportunities construct(List<SObject> sObjects)
        {
            return new Opportunities(sObjects);
        }
    }

    /**
     * Applies default values for newly created Opportunities.
     *
     * - CloseDate: if not provided, defaults to today + 30 days.
     * - Type:      if not provided, defaults to 'New Customer'.
     *
     * Runs only for inserts (onBeforeInsert), never on update, and only
     * fills values the caller has not set. Executed before insert so the
     * defaults are persisted in the same DML.
     */
    public override void onBeforeInsert()
    {
        for (Opportunity opp : (List<Opportunity>) getRecords())
        {
            if (opp.CloseDate == null)
            {
                opp.CloseDate = Date.today().addDays(30);
            }

            if (opp.Type == null)
            {
                opp.Type = 'New Customer';
            }
        }
    }
}
