public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate()
    {
        List<Opportunity> records = (List<Opportunity>) Record;
        Map<Id, SObject> originals = getOriginal();

        for (Opportunity record : records)
        {
            // Rule 1: on insert and on update, Amount must not be negative.
            if (record.Amount != null && record.Amount < 0)
            {
                Error('Amount cannot be negative.', record, Opportunity.Amount);
            }

            // Rule 2: on update, an opportunity whose stage was already Closed Won
            // before the update cannot have its Amount changed. Closing as won and
            // changing the amount in the same update is allowed, which is covered by
            // only comparing against the original (pre-update) values.
            Opportunity original = (Opportunity) originals.get(record.Id);
            if (original != null
                && original.StageName == STAGE_CLOSED_WON
                && isAmountChanged(original.Amount, record.Amount))
            {
                Error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
            }
        }
    }

    private static Boolean isAmountChanged(Decimal oldAmount, Decimal newAmount)
    {
        if (oldAmount == null)
        {
            return newAmount != null;
        }
        if (newAmount == null)
        {
            return true;
        }
        // BigDecimal.equals() is scale-sensitive, so compare numerically instead.
        return oldAmount.compareTo(newAmount) != 0;
    }
}
