public inherited sharing class ContactsSelector extends fflib_SObjectSelector
{
    private static final List<String> SELECT_FIELDS = new List<String>{
        'Id',
        'FirstName',
        'LastName',
        'Email',
        'Title',
        'AccountId'
    };

    public ContactsSelector()
    {
        // Keep the base class defaults (ordering by Name, default security settings)
        super();
    }

    public override Schema.SObjectType getSObjectType()
    {
        return Contact.SObjectType;
    }

    public override List<String> getSelectFields()
    {
        return SELECT_FIELDS.clone();
    }

    public List<Contact> selectById(Set<Id> contactIds)
    {
        // Guard clause: avoid an invalid `IN ()` predicate for an empty set
        if (contactIds == null || contactIds.isEmpty())
        {
            return new List<Contact>();
        }

        // newQueryFactory() builds the query from this selector's SObject type and
        // field list (Id is included automatically by the base class), preserving
        // the default ordering and security settings.
        String soql = newQueryFactory()
            .setCondition('Id IN :contactIds')
            .toSOQL();

        return (List<Contact>) Database.query(soql);
    }
}
