public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {
    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns up to maxRecords open opportunities for the given accounts, ordered by
     * Amount descending (opportunities without an Amount last), then by CloseDate ascending.
     * The query is built from the selector's query factory, so the selector's standard
     * field list and security (CRUD/FLS) settings continue to apply. A single SOQL
     * statement is executed, with the parent Account Name included via relationship path.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Nothing to query (an IN () condition is not valid SOQL)
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }
        // A non-positive limit cannot return any rows
        if (maxRecords != null && maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Uses the selector's field list and its configured CRUD/FLS enforcement
        fflib_QueryFactory queryFactory = newQueryFactory();

        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Highest Amount first, no-Amount rows last, ties broken by earliest CloseDate
        queryFactory.setSortOrder('Amount DESC NULLS LAST, CloseDate ASC');

        if (maxRecords != null) {
            queryFactory.setLimit(maxRecords);
        }

        // Parent Account Name as an additional (relationship-path) field
        queryFactory.addField('Account.Name');

        return (List<Opportunity>) Database.query(queryFactory.toSOQL());
    }
}
