public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';
    private static final String CONTACTS_RELATIONSHIP_NAME = 'Contacts';

    /**
     * No-argument constructor used by the Application selector factory.
     * Enforces CRUD, sharing and FLS, and runs every query in user mode
     * (WITH USER_MODE) so the platform enforces the running user's object,
     * field and sharing access on every query issued by this selector.
     */
    public AccountsSelector() {
        super(true, true, true, fflib_QueryFactory.QueryAccessLevel.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * Base fields plus every field currently in the Credit_Review field set.
     * Because newQueryFactory() (and therefore selectSObjectsById) sources its
     * fields from this method, field set fields are selected by every query,
     * including the ones executed by selectById and selectByIdWithContacts.
     * New fields added by admins are picked up without code changes.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        fields.addAll(getCreditReviewFieldSetFields());
        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns the accounts together with their Contacts child records in a
     * single query. fflib_QueryFactory has no native support for child
     * sub-selects, so the sub-query is added as a raw field expression. It is
     * built from ContactsSelector's field list, so the contact sub-query
     * always reflects that selector's fields, and it inherits this selector's
     * USER_MODE access level for the whole statement.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.addField(buildContactsSubQuery());
        queryFactory.setCondition('Id IN :accountIds');
        return (List<Account>) queryFactory.doQuery();
    }

    /**
     * Resolves the Credit_Review field set members to their corresponding
     * Account SObjectField tokens. Fields are resolved dynamically so no
     * field API names are hard-coded here; members that no longer exist in
     * the schema (e.g. a deleted custom field still listed in the field set)
     * are skipped defensively instead of producing a broken query.
     */
    private List<Schema.SObjectField> getCreditReviewFieldSetFields() {
        Map<String, Schema.SObjectField> accountFields =
            Account.SObjectType.getDescribe().fields.getMap();
        List<Schema.SObjectField> fieldSetFields = new List<Schema.SObjectField>();
        for (Schema.FieldSetMember member : Account.SObjectType
                .getDescribe()
                .fieldSets
                .getMap()
                .get(CREDIT_REVIEW_FIELD_SET)
                .getFields()) {
            Schema.SObjectField field = accountFields.get(
                member.getFieldName().toLowerCase()
            );
            if (field != null) {
                fieldSetFields.add(field);
            }
        }
        return fieldSetFields;
    }

    /**
     * Builds the Contacts sub-query from ContactsSelector so it uses that
     * selector's fields (Id, FirstName, LastName, Email, AccountId).
     */
    private String buildContactsSubQuery() {
        List<String> contactFieldPaths = new List<String>();
        for (Schema.SObjectField contactField : new ContactsSelector().getSObjectFieldList()) {
            contactFieldPaths.add(contactField.getDescribe().getName());
        }
        return '(SELECT '
            + String.join(contactFieldPaths, ', ')
            + ' FROM '
            + CONTACTS_RELATIONSHIP_NAME
            + ')';
    }
}
