/**
 * @description Service responsible for bulk-creating Accounts with their related
 *              Contacts in a single atomic Unit of Work commit.
 *
 *              All DML is delegated to fflib_SObjectUnitOfWork (Apex Enterprise
 *              Patterns); no direct DML statements are performed by this class.
 *              commitWork() results in exactly one insert per SObject type
 *              (one INSERT for all Accounts, one INSERT for all Contacts),
 *              keeping the service bulk-safe for hundreds of Contacts.
 */
public inherited sharing class AccountOnboardingService
{
    /**
     * @description Creates one Account per map key and one Contact (with the
     *              given LastName) per list entry, related to that Account.
     *              All records are registered on a single
     *              fflib_SObjectUnitOfWork and committed once via commitWork().
     *
     * @param  contactLastNamesByAccountName Map of Account Name -> List of
     *              Contact LastNames to create under that Account.
     * @return The newly created Accounts with their Ids populated after the
     *         commit. Empty list (no DML) when the input map is null or empty.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName)
    {
        // Nothing to do: return empty result and write nothing.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
        {
            return new List<Account>();
        }

        // Single Unit of Work covering both object types. Account is listed
        // first so it is inserted before its child Contacts on commitWork().
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>
            {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet())
        {
            Account account = new Account(Name = accountName);

            // Register the parent Account for insert.
            uow.registerNew(account);
            newAccounts.add(account);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null)
            {
                continue;
            }

            for (String lastName : lastNames)
            {
                // A Contact requires a LastName; skip null/blank entries so a
                // single bad list element cannot fail the whole commit.
                if (String.isBlank(lastName))
                {
                    continue;
                }

                Contact contact = new Contact(LastName = lastName);

                // Registers the Contact for insert and defers the AccountId
                // relationship; the Unit of Work sets the real Account Id on
                // the Contact during commitWork(), after the Account insert.
                uow.registerNew(contact, Contact.AccountId, account);
            }
        }

        // Single atomic commit: one INSERT for all Accounts, one INSERT for
        // all Contacts, parent Ids resolved onto the Contacts by the UoW.
        uow.commitWork();

        // The in-memory Account instances now carry their database Ids.
        return newAccounts;
    }
}
