public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        // Nothing to do for null or empty input
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load the opportunities with the selector
        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // One unit of work for both the updates and the platform events.
        // The fflib unit of work publishes registered platform events via
        // EventBus.publish during commitWork, only after the DML has committed,
        // so Fulfilment can never hear about a deal that failed to save.
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            // Skip opportunities already at Closed Won
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            // Stage to Closed Won with today's close date
            Opportunity wonOpportunity = new Opportunity(
                Id = opp.Id,
                StageName = 'Closed Won',
                CloseDate = Date.today()
            );
            uow.registerDirty(wonOpportunity);

            // Notify Fulfilment for every opportunity this method closes
            Deal_Won__e dealWonEvent = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            uow.registerNew(dealWonEvent);

            closedCount++;
        }

        if (closedCount > 0) {
            // Single commit: DML first, then the registered Deal_Won__e events
            // are published. If the DML fails, the exception propagates to the
            // caller and no events are published.
            uow.commitWork();
        }

        return closedCount;
    }
}
