public inherited sharing class ContactPhoneCleanup {

    /**
     * Normalizes the Phone field of the given contacts so it contains only
     * digits and plus signs (e.g. '+44 (20) 7946-0018' -> '+442079460018').
     *
     * - Contacts with no Phone value are skipped entirely.
     * - All updates are saved in a single Database.update(..., allOrNone=false)
     *   call, so one validation failure does not roll back the others.
     * - Returns a map from each contact Id that could NOT be saved to the
     *   message of its first error. Empty map when everything saved.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        // Only fetch contacts that actually have a phone to clean.
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
              AND Phone != null
        ];

        // Strip every character that is not a digit or a plus sign.
        for (Contact contact : contacts) {
            contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
        }

        // Single partial-success DML: a failing record does not block the rest.
        List<Database.SaveResult> saveResults = Database.update(contacts, false);

        // Collect the Ids that could not be saved, with their first error.
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (!result.isSuccess()) {
                errorsByContactId.put(
                    contacts[i].Id,
                    result.getErrors()[0].getMessage()
                );
            }
        }

        return errorsByContactId;
    }
}
