public with sharing class PipelineSummary {

    private static final List<String> MANAGED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the sum of Opportunity Amount for each of the four managed open
     * stages, for opportunities whose CloseDate falls within [fromDate, toDate],
     * both inclusive. Stages with no matching opportunities (or only null
     * amounts) map to 0, never null.
     *
     * One simple SUM(Amount) aggregate query per stage — always exactly four
     * queries regardless of data volume.
     *
     * @param fromDate inclusive lower bound on CloseDate
     * @param toDate   inclusive upper bound on CloseDate
     * @return map with exactly the four stage names as keys
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : MANAGED_STAGES) {
            // SUM() ignores null Amounts, and returns a single row (with a null
            // value) even when no records match — so no exception risk here.
            AggregateResult[] results = [
                SELECT SUM(Amount) stageTotal
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            Decimal stageTotal = 0;
            if (!results.isEmpty() && results[0].get('stageTotal') != null) {
                stageTotal = (Decimal) results[0].get('stageTotal');
            }
            totals.put(stage, stageTotal);
        }

        return totals;
    }
}
