/**
 * Recalculates the Rating of the related Account(s) from the open pipeline.
 *
 * Fires on:
 *  - insert of any opportunity,
 *  - update where StageName, Amount, or AccountId changed (AccountId changes
 *    are included so the account the opportunity moved AWAY from is also
 *    refreshed, otherwise it would keep a stale rating).
 *
 * All account ids touched by the batch are collected and sent to the async
 * service in ONE future call per transaction. A per-opportunity future call
 * would exceed the 50-future-calls-per-transaction governor limit on the
 * CPQ integration's 200-row batches and fail the save.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {

        Boolean relevant = Trigger.isInsert;

        if (Trigger.isUpdate) {
            Opportunity old = Trigger.oldMap.get(opp.Id);
            relevant = opp.StageName != old.StageName
                    || opp.Amount != old.Amount
                    || opp.AccountId != old.AccountId;

            // Account the opportunity may have moved away from.
            if (relevant && old.AccountId != null) {
                accountIds.add(old.AccountId);
            }
        }

        if (relevant && opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
