    /**
     * Applies the standard product discount to any new line whose Discount is null.
     * Lines with an explicit discount (including 0) are left untouched.
     * Runs in a before-insert trigger context, so no extra DML is needed.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // Collect the distinct products we actually need pricing for.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // One bulk query for product data (Family), regardless of line count.
        Map<Id, Product2> productsById = new Map<Id, Product2>(
            [SELECT Family FROM Product2 WHERE Id IN :productIds]
        );

        for (OpportunityLineItem line : newLines) {
            // Null check only: an explicitly entered 0 must be preserved.
            if (line.Discount == null && line.Product2Id != null) {
                Product2 product = productsById.get(line.Product2Id);
                line.Discount = PricingRules.standardDiscountForFamily(product?.Family);
            }
        }
    }
}
