trigger CaseTrigger on Case (after update) {
    // Only act on the actual transition to closed, not on any other update.
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);
        Boolean wasClosed = oldCase != null && oldCase.IsClosed;
        if (newCase.IsClosed && !wasClosed && newCase.ContactId != null) {
            newlyClosedCaseIds.add(newCase.Id);
        }
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // One Queueable per chunk of CHUNK_SIZE cases.
    // Apex allows at most 50 enqueueJob calls per transaction; with CHUNK_SIZE = 50
    // we support 2,500 newly closed cases in a single transaction while keeping each
    // chunk isolated in its own async transaction (one chunk's failure cannot
    // affect the others).
    final Integer CHUNK_SIZE = 50;

    for (Integer i = 0; i < newlyClosedCaseIds.size(); i += CHUNK_SIZE) {
        Integer endIndex = Math.min(i + CHUNK_SIZE, newlyClosedCaseIds.size());
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds.subList(i, endIndex)));
    }
}
