public with sharing class AccountCountrySync {

    /**
     * After an Account's BillingCountry changes, propagate the new BillingCountry to the
     * MailingCountry of its contacts, but only for contacts whose MailingCountry is blank
     * or still equals the account's PREVIOUS BillingCountry. Contacts that have their own
     * (different) country are left untouched, as are accounts whose BillingCountry did not
     * change.
     *
     * Bulk-safe: one selective contact query per transaction, no queries inside loops,
     * no DML inside loops.
     */
    public static void syncBillingCountryToContacts(List<Account> newAccounts, Map<Id, Account> oldMap) {

        // Identify accounts whose BillingCountry actually changed.
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Set<String> previousCountries = new Set<String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc != null && oldAcc.BillingCountry != acc.BillingCountry) {
                changedAccountIds.add(acc.Id);
                newCountryByAccountId.put(acc.Id, acc.BillingCountry);
                if (oldAcc.BillingCountry != null) {
                    previousCountries.add(oldAcc.BillingCountry);
                }
            }
        }

        // Nothing to do if no BillingCountry changed in this batch.
        if (changedAccountIds.isEmpty()) {
            return;
        }

        // Single selective query: only contacts of the changed accounts, and only those
        // whose MailingCountry is blank or matches one of the previous BillingCountry
        // values. A contact can only belong to one account, so matching against the
        // combined set of previous countries is equivalent to matching its own account's
        // previous country. Old BillingCountry = null is covered by MailingCountry = null.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : [
                SELECT Id, AccountId, MailingCountry
                FROM Contact
                WHERE AccountId IN :changedAccountIds
                  AND (MailingCountry = null OR MailingCountry IN :previousCountries)
        ]) {
            String newCountry = newCountryByAccountId.get(con.AccountId);

            // Only stage contacts that actually need to change (e.g. MailingCountry was
            // blank and the new BillingCountry is also null, or they are already equal).
            if (con.MailingCountry != newCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

