```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    errorMessage;
    searchPending = false;

    requestId = 0;
    debounceTimeoutId;

    get hasResults() {
        return this.contacts.length > 0;
    }

    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        const trimmedTerm = this.searchTerm.trim();

        // Any new keystroke invalidates the previously scheduled search.
        clearTimeout(this.debounceTimeoutId);
        this.debounceTimeoutId = undefined;

        // Invalidate any in-flight request: its response must be ignored.
        this.requestId += 1;

        if (trimmedTerm.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this.errorMessage = undefined;
            this.searchPending = false;
            return;
        }

        // Capture the id of the request we are about to schedule so that,
        // when the response arrives, we can verify it is still the most recent.
        const requestIdForThisSearch = this.requestId;

        this.debounceTimeoutId = setTimeout(() => {
            this.runSearch(trimmedTerm, requestIdForThisSearch);
        }, DEBOUNCE_DELAY_MS);
    }

    async runSearch(trimmedTerm, requestIdForThisSearch) {
        this.searchPending = true;
        try {
            const results = await searchContacts({ searchTerm: trimmedTerm });
            // Ignore stale responses that arrive out of order, and ignore
            // any response if the component has been disconnected.
            if (requestIdForThisSearch !== this.requestId || !this.isConnected) {
                return;
            }
            this.contacts = results;
            this.errorMessage = undefined;
        } catch (error) {
            if (requestIdForThisSearch !== this.requestId || !this.isConnected) {
                return;
            }
            this.contacts = [];
            this.errorMessage = error.body ? error.body.message : error.message;
        } finally {
            if (requestIdForThisSearch === this.requestId && this.isConnected) {
                this.searchPending = false;
            }
        }
    }

    disconnectedCallback() {
        // Cancel a pending debounced search...
        clearTimeout(this.debounceTimeoutId);
        this.debounceTimeoutId = undefined;
        // ...and invalidate any in-flight request so its response is ignored.
        this.requestId += 1;
    }

    renderedCallback() {
        // No-op: kept intentionally empty to document that no DOM
        // manipulation is required; results are fully data-driven.
    }
}
