    columns = COLUMNS;
    draftValues = [];
    contacts = [];

    wiredContactsResult;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredContactsResult = result;
        this.contacts = result.data ? result.data : [];
    }

    handleSave(event) {
        const drafts = event.detail.draftValues;
        const savePromises = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        Promise.all(savePromises)
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Contacts updated',
                        variant: 'success'
                    })
                );
                this.draftValues = [];
                return refreshApex(this.wiredContactsResult);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
}
