    get buttonLabel() {
        // The action a click performs is the opposite of the current state.
        return this.favorite ? Favorite_Remove : Favorite_Add;
    }

    get iconName() {
        return this.favorite ? 'utility:favorites' : 'utility:favorite';
    }

    handleClick() {
        // Optimistic UI: flip the shown state immediately, then notify the parent.
        const newFavorite = !this.favorite;
        this._favorite = newFavorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newFavorite },
            }),
