import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    opportunities = [];
    error;
    isLoading = false;

    connectedCallback() {
        this.loadOpportunities();
    }

    loadOpportunities() {
        this.isLoading = true;
        this.error = undefined;
        this.opportunities = [];

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result ?? [];
                this.error = undefined;
            })
            .catch((err) => {
                this.error = err;
                this.opportunities = [];
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasError() {
        return this.error !== undefined;
    }

    get errorMessage() {
        return this.error?.body?.message ?? 'An unknown error occurred';
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }
}
