import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    /** Controls visibility of the submit error message. */
    showErrors = false;

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        // querySelectorAll returns editors in display order.
        this.template.querySelectorAll('c-line-item-editor').forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = Array.from(this.template.querySelectorAll('c-line-item-editor'));

        // Validate every editor unconditionally so all invalid lines show their
        // errors at once, even if an earlier line already reported a problem.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((isValid) => isValid === true);

        if (allValid) {
            this.showErrors = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines },
                })
            );
        } else {
            this.showErrors = true;
        }
    }
}
