import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    statsLoaded = false;
    error;

    isInFlight = false;
    pollTimerId;

    connectedCallback() {
        // Load immediately on insertion (load() itself guards against making
        // requests while the tab is hidden).
        this.load();

        // Start the polling loop. Only one loop is ever created because
        // connectedCallback runs once per lifecycle and disconnectedCallback
        // always clears the timer.
        this.pollTimerId = setInterval(() => {
            this.load();
        }, REFRESH_INTERVAL_MS);

        // Bound arrow function keeps a stable reference so we can remove the
        // listener exactly once in disconnectedCallback.
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        // Stop all polling and stop listening; nothing keeps running or
        // calling Apex after removal.
        if (this.pollTimerId !== undefined) {
            clearInterval(this.pollTimerId);
            this.pollTimerId = undefined;
        }
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        // When the console tab becomes visible again, refresh immediately.
        // The interval keeps ticking in the background; while hidden, load()
        // makes no requests, so nothing fires until the page is visible.
        if (document.visibilityState === 'visible') {
            this.load();
        }
    };

    async load() {
        // Never start a request while the previous one is in flight, and
        // never make requests while the page is hidden (background tabs).
        if (this.isInFlight || document.visibilityState === 'hidden') {
            return;
        }
        this.isInFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.statsLoaded = true;
            // A successful refresh clears any previously shown error.
            this.error = undefined;
        } catch (e) {
            this.error = e;
            // Keep polling; the error stays visible until the next success.
        } finally {
            this.isInFlight = false;
        }
    }

    get errorMessage() {
        return this.error ? this.error.body?.message : undefined;
    }
}
