        // Step 2: report validity on every input so all messages show at once.
        const inputs = this.template.querySelectorAll('lightning-input');
        const allValid = Array.from(inputs).every((input) => input.reportValidity());

        // Step 3: stop if anything is invalid; otherwise call Apex imperatively.
        if (!allValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
