import { LightningElement, api } from 'lwc';

let instanceUid = 0;

const NAVIGATION_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox (exposed as aria-label). */
    @api label = '';

    /** Array of { value, label }. */
    @api options = [];

    /** Stable prefix for option ids, used by aria-activedescendant. */
    idBase;

    /** Currently selected value (may be empty). */
    _value = '';

    /** Explicitly set active index; undefined means "derive from selection". */
    _activeIndex;

    constructor() {
        super();
        instanceUid += 1;
        this.idBase = `status-listbox-${instanceUid}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue == null ? '' : newValue;
        const idx = this.selectedIndex;
        if (idx >= 0) {
            // Parent set a valid value: selection and active option move to it.
            this._activeIndex = idx;
        } else if (this._value === '') {
            // Nothing selected anymore: fall back to the first option.
            this._activeIndex = 0;
        }
    }

    /** Index of the selected option, or -1 when nothing is selected. */
    get selectedIndex() {
        return this.safeOptions.findIndex((opt) => opt.value === this._value);
    }

    /** Index of the active option, clamped to the available options. */
    get activeIndex() {
        const length = this.safeOptions.length;
        if (length === 0) {
            return 0;
        }
        if (this._activeIndex === undefined) {
            // Initial state: the selected option, or the first option.
            const idx = this.selectedIndex;
            return idx >= 0 ? idx : 0;
        }
        return Math.min(Math.max(this._activeIndex, 0), length - 1);
    }

    set activeIndex(index) {
        this._activeIndex = index;
    }

    /** Guard against parents passing undefined/null for options. */
    get safeOptions() {
        return Array.isArray(this.options) ? this.options : [];
    }

    /** Options enriched with ids, aria-selected and styling hooks. */
    get renderedOptions() {
        const selected = this.selectedIndex;
        const active = this.activeIndex;
        return this.safeOptions.map((option, index) => ({
            ...option,
            id: `${this.idBase}-option-${index}`,
            ariaSelected: index === selected ? 'true' : 'false',
            itemClass: index === active ? 'option option--active' : 'option',
        }));
    }

    /** Id of the active option, or null (attribute omitted) when empty. */
    get ariaActiveDescendant() {
        if (this.safeOptions.length === 0) {
            return null;
        }
        return `${this.idBase}-option-${this.activeIndex}`;
    }

    /**
     * Keyboard handling per the WAI-ARIA listbox pattern.
     * DOM focus stays on the listbox; only aria-activedescendant moves.
     */
    handleKeyDown(event) {
        // Only intercept the six keys we own; Tab and everything else keep
        // their default behaviour.
        if (!NAVIGATION_KEYS.includes(event.key)) {
            return;
        }
        event.preventDefault();

        const length = this.safeOptions.length;
        if (length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                // No wrap-around: stop at the last option.
                this.activeIndex = Math.min(this.activeIndex + 1, length - 1);
                break;
            case 'ArrowUp':
                // No wrap-around: stop at the first option.
                this.activeIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(this.activeIndex);
                break;
            default:
                break;
        }
    }

    /** Clicking an option selects it and makes it the active option. */
    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this.safeOptions.findIndex((opt) => opt.value === value);
        if (index === -1) {
            return;
        }
        this.activeIndex = index;
        this.selectIndex(index);
    }

    /**
     * Select the option at the given index and notify the parent.
     * Moving the active option never changes the selection, and selecting an
     * already-selected option dispatches nothing.
     */
    selectIndex(index) {
        const option = this.safeOptions[index];
        if (!option || option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
            })
        );
    }
}
