import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Backing fields. All fields are reactive in LWC, so direct assignment
    // (this.items = ...) triggers re-render; no @track needed.
    _heading = '';
    items = [];
    newLabel = '';
    nextId = 1;

    /**
     * Public heading. Display-only: we keep an upper-cased copy for rendering
     * and never mutate the value the parent set. Using a setter (instead of
     * mutating in connectedCallback) also guarantees that later changes by
     * the parent are reflected.
     */
    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value ? String(value).toUpperCase() : '';
    }

    /**
     * Public tasks. The component always works on its own deep-enough copy,
     * so the parent's array and task objects are never modified. Assigning a
     * new array from the parent replaces the list with a copy of it.
     */
    @api
    get tasks() {
        return this.items;
    }
    set tasks(value) {
        this.items = Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return; // empty or whitespace-only labels are ignored
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label, done: false },
        ];
        // Dispatch with the label that was actually added, then clear the input.
        this.dispatchEvent(
            new CustomEvent('taskadded', { detail: { label } })
        );
        this.newLabel = '';
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        // Build a new list (and new task object for the toggled task) rather
        // than mutating in place: reliably reactive and never touches the
        // parent's data.
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
