 * - The "standard mechanism" for changing a contact's employer is to insert or
 *   update a single npe5__Affiliation__c record with npe5__Status__c = 'Current'
 *   and npe5__Primary__c = true. The NPSP Affiliation trigger then:
 *       1. demotes any other Current, primary affiliation of the same Contact
 *          (sets npe5__Primary__c = false, npe5__Status__c = 'Former' and stamps
 *          npe5__EndDate__c), and
 *       2. maintains Contact.npsp__Primary_Affiliation__c so it points at the
 *          organization Account of the Current primary affiliation.
 *   We therefore never write to the old primary affiliation or to the Contact
 *   ourselves - NPSP maintains both, which keeps us within the DML budget and
 *   guarantees the Contact's household AccountId is untouched.
 *
 * - Idempotency / no duplicates: exactly one SOQL query fetches all existing
 *   affiliations between the affected Contacts and the target Organizations.
 *   If the Contact already has a Current, primary affiliation to the target
 *   organization, nothing is written at all.
 *
 * - Limits: 1 SOQL query, at most 2 DML statements (one insert, one update),
 *   fully bulkified for 200+ Contacts per call.
 */
public inherited sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';

    /**
     * @description For each entry, makes `organizationId` the Contact's current
     *              employer via a Current, primary NPSP affiliation, and points
     *              the Contact's primary affiliation lookup at that organization
     *              (maintained by NPSP). A previously Current primary employer is
     *              demoted to Former/non-primary with an end date of today by the
     *              NPSP trigger. Null or empty input is a no-op.
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // Null or empty map: do nothing.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Sanitize: ignore null keys/values rather than failing the whole batch.
        Map<Id, Id> requests = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                requests.put(contactId, orgId);
            }
        }
        if (requests.isEmpty()) {
            return;
        }

        Set<Id> contactIds = requests.keySet();
        Set<Id> orgIds = new Set<Id>(requests.values());

        // SOQL query #1 (only one used): existing affiliations between these
        // Contacts and these Organizations, in any status. This is everything
        // needed to avoid duplicates and to decide insert vs. update vs. no-op.
        // Contact Id -> (Organization Id -> Affiliation)
        Map<Id, Map<Id, npe5__Affiliation__c>> existingByContact =
            new Map<Id, Map<Id, npe5__Affiliation__c>>();

        for (npe5__Affiliation__c aff : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Organization__c IN :orgIds
        ]) {
            Map<Id, npe5__Affiliation__c> byOrg = existingByContact.get(aff.npe5__Contact__c);
            if (byOrg == null) {
                byOrg = new Map<Id, npe5__Affiliation__c>();
                existingByContact.put(aff.npe5__Contact__c, byOrg);
            }
            // If dirty data contains more than one affiliation for the same
            // contact/org pair, prefer the one that is already Current+Primary.
            npe5__Affiliation__c kept = byOrg.get(aff.npe5__Organization__c);
            if (kept == null || (!isCurrentPrimary(kept) && isCurrentPrimary(aff))) {
                byOrg.put(aff.npe5__Organization__c, aff);
            }
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : requests.keySet()) {
            Id orgId = requests.get(contactId);

            npe5__Affiliation__c existing = null;
            if (existingByContact.containsKey(contactId)) {
                existing = existingByContact.get(contactId).get(orgId);
            }

            if (existing == null) {
                // New employment: insert a Current, primary affiliation.
                // NPSP's trigger demotes any existing Current primary affiliation
                // of this contact (Former, non-primary, End Date = today) and
                // repoints Contact.npsp__Primary_Affiliation__c to orgId.
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c      = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c       = STATUS_CURRENT,
                    npe5__Primary__c      = true,
                    npe5__StartDate__c    = Date.today()
                ));
            } else if (isCurrentPrimary(existing)) {
                // The organization already is the contact's Current primary
                // affiliation: nothing changes, no DML for this contact.
                continue;
            } else {
                // An affiliation to this organization exists but is not the
                // Current primary one (e.g. a Former stint, or a Current
                // non-primary record). Promote/reactivate it in place - this
                // avoids creating a duplicate. NPSP's trigger handles the old
                // primary employer and the Contact lookup.
                Boolean wasNotCurrent = existing.npe5__Status__c != STATUS_CURRENT;
                existing.npe5__Status__c  = STATUS_CURRENT;
                existing.npe5__Primary__c = true;
                existing.npe5__EndDate__c = null;
                // Re-employment after a break starts a new spell; also covers a
                // record that never had a start date.
                if (wasNotCurrent || existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = Date.today();
                }
                toUpdate.add(existing);
            }
        }

        // DML statement #1.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        // DML statement #2.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }

    /**
     * @description True if the affiliation is the Current, primary one.
     */
    private static Boolean isCurrentPrimary(npe5__Affiliation__c aff) {
        return aff.npe5__Primary__c == true && STATUS_CURRENT.equals(aff.npe5__Status__c);
    }
}
