/**
 * @description GiftImportService
 *
 * Service for importing one-off website gifts into NPSP via the NPSP Data
 * Importer (BDI) Apex API instead of inserting Contacts and Opportunities
 * directly. By routing every gift through a staged `npsp__DataImport__c`
 * record and NPSP's own import engine, the org's Data Import settings
 * (`npsp__Data_Import_Settings__c` — by default matching Contacts on
 * first name + last name + email and never matching existing donations)
 * govern contact matching, household creation and donation processing.
 *
 * The staged `npsp__DataImport__c` records are left in the org: the Apex
 * API (`npsp.DataImportAPI.run`) processes each record in place, writing
 * `npsp__Status__c`, `npsp__Contact1Imported__c`, `npsp__DonationImported__c`
 * and `npsp__FailureInformation__c` back onto the record. Unlike the
 * Visualforce/scheduled-batch flow, the Apex API does not delete the rows
 * after processing, so every row remains as the audit trail of what was
 * imported.
 *
 * Bulk-safe: all gifts are staged with a single DML statement, handed to the
 * NPSP API in a single synchronous call (same transaction), and results are
 * read back with a single query. 200 gifts in one call is well within limits.
 *
 * Error isolation: NPSP's BDI engine uses partial-success DML internally and
 * writes per-row failure information, so a rejected row never blocks the
 * other rows. Rows that fail staging (before NPSP ever sees them) or a hard
 * API failure are reported individually in the corresponding ImportResult
 * and also never stop the rest of the batch.
 */
public with sharing class GiftImportService {

    /** One website gift. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for one gift, in the same order as the input. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /** Status value NPSP writes back on a successfully imported row. */
    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * @description Imports one-off website gifts through NPSP's Data Importer.
     * @param gifts the gifts from the website (may be null or empty)
     * @return one ImportResult per gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // One result slot per gift, index-aligned with the input list.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
        }

        // ------------------------------------------------------------------
        // 1. Stage one NPSP Data Import record per gift (single DML, partial
        //    success so a bad stage row cannot block the rest).
        // ------------------------------------------------------------------
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            ));
        }

        // Map of staged record Id -> index in the input list, so NPSP's
        // write-backs can be folded back into the right ImportResult.
        Map<Id, Integer> indexById = new Map<Id, Integer>();

        Database.SaveResult[] stageResults = Database.insert(staged, false);
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        for (Integer i = 0; i < stageResults.size(); i++) {
            if (stageResults[i].isSuccess()) {
                indexById.put(staged[i].Id, i);
                toProcess.add(staged[i]);
            } else {
                // Staging itself was rejected; report it without stopping the others.
                results[i].success = false;
                results[i].errorMessage = joinErrors(stageResults[i].getErrors());
            }
        }

        // ------------------------------------------------------------------
        // 2. Hand everything to NPSP's Data Importer Apex API. This runs the
        //    BDI engine synchronously, in this transaction, using the org's
        //    Data Import settings. NPSP updates each record in place and
        //    leaves it in the org as the audit trail.
        // ------------------------------------------------------------------
        if (!toProcess.isEmpty()) {
            try {
                npsp.DataImportAPI.run(toProcess);
            } catch (Exception e) {
                // The API itself blew up. Report every outstanding row as
                // failed; the staged records remain in the org for auditing.
                for (npsp__DataImport__c di : toProcess) {
                    Integer idx = indexById.get(di.Id);
                    results[idx].success = false;
                    results[idx].errorMessage = 'NPSP data import error: ' + e.getMessage();
                }
                return results;
            }
        }

        // ------------------------------------------------------------------
        // 3. Read NPSP's write-backs back and build the results, in input
        //    order (single query, no SOQL in loops).
        // ------------------------------------------------------------------
        if (!toProcess.isEmpty()) {
            Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :toProcess
            ]);

            for (npsp__DataImport__c di : toProcess) {
                Integer idx = indexById.get(di.Id);
                npsp__DataImport__c p = processed.get(di.Id);

                if (p != null && p.npsp__Status__c == STATUS_IMPORTED) {
                    results[idx].success = true;
                    results[idx].contactId = p.npsp__Contact1Imported__c;
                    results[idx].opportunityId = p.npsp__DonationImported__c;
                } else {
                    results[idx].success = false;
                    results[idx].errorMessage =
                        (p != null && String.isNotBlank(p.npsp__FailureInformation__c))
                            ? p.npsp__FailureInformation__c
                            : 'NPSP data import did not complete for this row.';
                }
            }
        }

        return results;
    }

    /**
     * @description Flattens DML errors from a partial-success SaveResult into
     *              a single readable message.
     * @param errors the errors reported for one row
     * @return a semicolon-delimited error string (never null)
     */
    private static String joinErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'Unknown error staging the NPSP Data Import record.';
        }
        List<String> messages = new List<String>();
        for (Database.Error err : errors) {
            messages.add(err.getStatusCode() + ': ' + err.getMessage());
        }
        return String.join(messages, '; ');
    }
}
