/**
 * @description Creates Enhanced Recurring Donations (NPSP) for monthly giving
 * sign-ups submitted by the donation form.
 *
 * Design notes:
 * - Validation of every request happens up front, before any DML, so an invalid
 *   batch never leaves partial data behind.
 * - The service performs no SOQL at all and exactly one DML statement
 *   (a single bulkified insert), so a 200-request call uses 0 queries and 1 DML.
 * - NPSP's own Enhanced Recurring Donations machinery generates the installment
 *   Opportunities; this class never inserts Opportunities itself.
 * - "Day 31" is expressed with the Enhanced RD "always use last day of month"
 *   option; days 29 and 30 are stored literally as those days.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    /** One monthly-giving sign-up coming from the donation form. */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31 (31 = last day of the month)
        public Date startDate;
        public Integer installments;  // null or 0 = no end date (open ended)
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String SCHEDULE_TYPE_FIXED = 'Fixed Length';
    private static final String SCHEDULE_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String STATUS_ACTIVE = 'Active';
    private static final String PERIOD_MONTHLY = 'Monthly';
    private static final Integer LAST_DAY_OF_MONTH = 31;

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests the sign-ups from the donation form
     * @return the Ids of the newly created npe03__Recurring_Donation__c records,
     *         in the same order as the requests
     * @throws RecurringGiftService.RecurringGiftException if any request is invalid
     *         (nothing is inserted in that case)
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // Null or empty input is a no-op, not an error.
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate everything before any DML so invalid batches are rejected atomically.
        validate(requests);

        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            recurringDonations.add(buildRecurringDonation(request));
        }

        // Single bulkified DML statement. NPSP triggers on
        // npe03__Recurring_Donation__c generate the installment Opportunities.
        insert recurringDonations;

        List<Id> resultIds = new List<Id>();
        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            resultIds.add(rd.Id);
        }
        return resultIds;
    }

    /**
     * Throws a RecurringGiftException listing every invalid request in the batch.
     */
    private static void validate(List<GiftRequest> requests) {
        List<String> errors = new List<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];

            if (request == null) {
                errors.add('Request at index ' + i + ' is null.');
                continue;
            }
            if (request.contactId == null) {
                errors.add('Request at index ' + i + ': contactId is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                errors.add('Request at index ' + i + ': amount must be greater than zero.');
            }
            if (request.dayOfMonth == null
                    || request.dayOfMonth < 1
                    || request.dayOfMonth > LAST_DAY_OF_MONTH) {
                errors.add('Request at index ' + i
                    + ': dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                errors.add('Request at index ' + i + ': startDate is required.');
            }
        }

        if (!errors.isEmpty()) {
            throw new RecurringGiftException(
                'Invalid recurring gift request(s): ' + String.join(errors, ' | '));
        }
    }

    /**
     * Maps one GiftRequest to an Enhanced Recurring Donation record.
     */
    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest request) {
        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

        // Donor and money.
        rd.npe03__Contact__c = request.contactId;
        rd.npe03__Amount__c = request.amount;

        // Monthly schedule, every month (frequency 1), on the given day of month.
        rd.npe03__Installment_Period__c = PERIOD_MONTHLY;
        rd.npsp__InstallmentFrequency__c = 1;
        if (request.dayOfMonth == LAST_DAY_OF_MONTH) {
            // Enhanced RD's own "last day of month" option; Day_of_Month__c is
            // intentionally not set so the checkbox governs the schedule.
            rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
        } else {
            // 29 and 30 are stored as those days.
            rd.npsp__Day_of_Month__c = request.dayOfMonth;
        }
        rd.npsp__StartDate__c = request.startDate;

        // Open ended vs. fixed length.
        boolean isOpenEnded = (request.installments == null || request.installments == 0);
        if (isOpenEnded) {
            rd.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
            rd.npe03__Schedule_Type__c = SCHEDULE_TYPE_OPEN;
            rd.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
        } else {
            rd.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            rd.npe03__Schedule_Type__c = SCHEDULE_TYPE_FIXED;
            rd.npe03__Installments__c = request.installments;
        }

        // Status, payment method and dates.
        rd.npsp__Status__c = STATUS_ACTIVE;
        rd.npsp__PaymentMethod__c = request.paymentMethod;
        rd.npe03__Date_Established__c = request.startDate;
        rd.npe03__Next_Payment_Date__c = firstPaymentDate(request.startDate, request.dayOfMonth);

        return rd;
    }

    /**
     * Returns the first scheduled payment date on or after the start date,
     * honoring the last-day-of-month semantics for day 31 (and clamping to the
     * month's last day when the requested day does not exist in that month).
     */
    private static Date firstPaymentDate(Date startDate, Integer dayOfMonth) {
        Integer year = startDate.year();
        Integer month = startDate.month();

        // One full year of lookahead is always sufficient for a monthly schedule.
        for (Integer i = 0; i < 12; i++) {
            Integer daysInMonth = Date.daysInMonth(year, month);
            Integer effectiveDay = Math.min(dayOfMonth, daysInMonth);
            Date candidate = Date.newInstance(year, month, effectiveDay);

            if (!candidate.before(startDate)) {
                return candidate;
            }

            month++;
            if (month > 12) {
                month = 1;
                year++;
            }
        }

        // Unreachable for a valid monthly schedule; kept as a defensive fallback.
        return startDate;
    }
}
