/**
 * GauAllocationService
 *
 * Creates percentage-based GAU Allocations (npsp__Allocation__c) for an Opportunity,
 * replacing any existing GAU Allocations on that Opportunity.
 *
 * Design notes:
 * - We populate npsp__Percent__c (not npsp__Amount__c). NPSP's allocation logic computes
 *   npsp__Amount__c from npsp__Percent__c and the Opportunity Amount at insert time, and
 *   automatically recalculates the Amounts of allocations that carry a Percent value
 *   whenever the Opportunity Amount changes afterwards. That keeps a 60/40 split correct
 *   at $1,000 ($600/$400) and at $2,000 ($1,200/$800) with no further code.
 * - All validation happens before any DML. The replace operation (delete old + insert new)
 *   is wrapped in a savepoint so a partial failure rolls back cleanly and is surfaced as
 *   GauAllocationService.AllocationException.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal HUNDRED = 100;

    /**
     * Replaces all existing GAU Allocations of the given Opportunity with one allocation
     * per map entry, using the entry's percentage.
     *
     * @param opportunityId  the Opportunity to allocate
     * @param percentByGauId map of npsp__General_Accounting_Unit__c Id -> percentage
     *                       (60 means 60%). Totals below 100 are allowed; the remainder
     *                       stays unallocated.
     * @return the inserted npsp__Allocation__c records (requeried so NPSP-computed
     *         values, e.g. npsp__Amount__c, are populated)
     * @throws GauAllocationService.AllocationException on any validation or DML failure
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ------------------------------------------------------------------
        // Validation (nothing is modified until all checks pass)
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id must not be null.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The allocation map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0 (got ' + percent + ').');
            }
            totalPercent += percent;
        }
        if (totalPercent > HUNDRED) {
            throw new AllocationException(
                'Percentages total ' + totalPercent + '%; the total must not exceed 100%.');
        }

        // GAUs must exist and be active.
        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'GAU ' + gauId + ' does not exist or is not visible to the current user.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU "' + gau.Name + '" (' + gauId + ') is inactive.');
            }
        }

        // The Opportunity must exist.
        Integer oppCount = [SELECT COUNT() FROM Opportunity WHERE Id = :opportunityId];
        if (oppCount == 0) {
            throw new AllocationException(
                'Opportunity ' + opportunityId + ' does not exist or is not visible to the current user.');
        }

        // ------------------------------------------------------------------
        // Replace existing allocations atomically
        // ------------------------------------------------------------------
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        Savepoint savepoint = Database.setSavepoint();
        try {
            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }

            List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
            for (Id gauId : percentByGauId.keySet()) {
                newAllocations.add(new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percentByGauId.get(gauId)
                ));
            }
            insert newAllocations;

            // Requery so the returned records include values NPSP calculated on insert
            // (notably npsp__Amount__c, derived from npsp__Percent__c and the Opportunity Amount).
            Map<Id, npsp__Allocation__c> insertedById = new Map<Id, npsp__Allocation__c>(
                [SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c,
                        npsp__Amount__c, npsp__Percent__c
                 FROM npsp__Allocation__c
                 WHERE Id IN :newAllocations]
            );
            return insertedById.values();

        } catch (DmlException e) {
            Database.rollback(savepoint);
            throw new AllocationException(
                'Failed to replace GAU allocations for Opportunity ' + opportunityId + ': ' + e.getMessage());
        }
    }
}
