/**
 * Service for the event check-in app: registers a family (one or more new
 * Contacts) in a single call and puts all of them into ONE new NPSP
 * Household Account.
 *
 * Design notes:
 * - The household Account is created up front with the NPSP Household Account
 *   record type (looked up by DeveloperName, never by hard-coded Id) and the
 *   Contacts are then assigned to it. If we simply inserted the Contacts
 *   without an AccountId, NPSP's trigger framework would create a separate
 *   household for each Contact, leaving extra empty households behind.
 * - We never set the final household name ourselves. Account.Name is a
 *   required platform field, so a temporary value is supplied on insert;
 *   NPSP's Household Naming (which reacts to the Contact and Account
 *   triggers below) overwrites it with the calculated name and generates
 *   the household greetings from the members.
 * - All DML is bulk-safe: the members are inserted in a single statement and
 *   any failure rolls the whole transaction back, so no partial or orphaned
 *   accounts are ever left behind.
 */
public inherited sharing class HouseholdService {

    /**
     * DeveloperName of the NPSP Household Account record type in this org.
     * Resolved by DeveloperName (not hard-coded Id) so it works in any org
     * and across sandboxes/production.
     */
    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /**
     * Creates one NPSP household Account and inserts all given new Contacts
     * into it, with the first Contact in the list becoming the household's
     * primary contact (Account.npe01__One2OneContact__c).
     *
     * NPSP names the household and generates its greetings automatically via
     * its own trigger logic; this method only supplies a temporary placeholder
     * name to satisfy the required Account.Name field.
     *
     * @param members new Contacts (no Id, no AccountId) to place in the household
     * @return the Id of the newly created household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold: members must contain at least one Contact.'
            );
        }

        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // 1. Create the household Account first so every member lands in the
        //    same household. Record type HH_Account makes NPSP treat it as a
        //    household (naming, greetings, One-to-One handling, etc.).
        //    The Name value below is temporary; NPSP's Household Naming
        //    replaces it once the members are inserted.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = 'New Household'
        );
        insert household;

        // 2. Point every member at the household and insert them in one bulk
        //    DML statement. NPSP's Contact trigger then fires the Household
        //    Naming logic, which renames the household and builds the
        //    greetings from the new members.
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // 3. Flag the first member in the list as the household's primary
        //    contact. This Account update also gives NPSP's trigger framework
        //    a second pass at Household Naming now that members exist.
        update new Account(
            Id = household.Id,
            npe01__One2OneContact__c = members[0].Id
        );

        return household.Id;
    }

    /**
     * Resolves the Id of the active NPSP Household Account record type by its
     * DeveloperName. Never hard-codes a record type Id, so the service works
     * unchanged across sandboxes and production.
     */
    private static Id getHouseholdRecordTypeId() {
        return [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RECORD_TYPE_DEV_NAME
              AND IsActive
            LIMIT 1
        ].Id;
    }
}
