/**
 * @description Service for creating/updating NPSP partial soft credits for
 * peer-to-peer fundraising integrations.
 *
 * For each SoftCreditRequest:
 *   - The contact ends up with exactly one OpportunityContactRole on the
 *     opportunity whose Role equals the requested role. If the contact already
 *     has a contact role there (e.g. the "Household Member" role NPSP adds for
 *     household members), that role is renamed to the requested role; if the
 *     contact has no contact role there, one is created.
 *   - The contact ends up with exactly one npsp__Partial_Soft_Credit__c on the
 *     opportunity, linked (via npsp__Contact_Role_ID__c) to that contact role,
 *     with npsp__Amount__c = amount and npsp__Role_Name__c = role. An existing
 *     partial soft credit for the same opportunity/contact pair is updated in
 *     place rather than duplicated.
 *
 * All validation happens before any DML: if any request is invalid, a
 * SoftCreditException is thrown and nothing is changed.
 *
 * Limits: for 200 requests this uses at most 3 SOQL queries and at most
 * 4 DML statements.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    /** One partial soft credit to apply. */
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Applies a batch of partial soft credit requests.
     *
     * @param requests the partial soft credits to apply; null/empty is a no-op.
     * @throws SoftCreditService.SoftCreditException if any request is invalid
     *         (contact is the opportunity's primary contact; amount is null,
     *         non-positive, or greater than the opportunity amount; role is
     *         blank; opportunity/contact unknown; duplicate pair). Nothing is
     *         written when this is thrown.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> seenPairs = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest request = requests[i];
            if (request == null || request.opportunityId == null || request.contactId == null) {
                throw new SoftCreditException(
                    'SoftCreditService: request at index ' + i +
                    ' must specify both opportunityId and contactId.');
            }
            String pair = pairKey(request.opportunityId, request.contactId);
            if (!seenPairs.add(pair)) {
                throw new SoftCreditException(
                    'SoftCreditService: duplicate opportunity/contact pair in request at index ' + i +
                    ' (Opportunity ' + request.opportunityId + ', Contact ' + request.contactId + ').');
            }
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        // ------------------------------------------------------------------
        // SOQL 1: opportunities - needed for validation (primary contact,
        // amount) and as the parent of the partial soft credits.
        // ------------------------------------------------------------------
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id,
                   Amount,
                   npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // ------------------------------------------------------------------
        // SOQL 2: existing contact roles for the requested pairs.
        // ------------------------------------------------------------------
        Map<String, OpportunityContactRole> contactRolesByPair = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole contactRole : [
            SELECT Id,
                   OpportunityId,
                   ContactId,
                   Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            contactRolesByPair.put(
                pairKey(contactRole.OpportunityId, contactRole.ContactId),
                contactRole
            );
        }

        // ------------------------------------------------------------------
        // SOQL 3: existing partial soft credits for the requested pairs, so we
        // update instead of creating duplicates.
        // ------------------------------------------------------------------
        Map<String, npsp__Partial_Soft_Credit__c> softCreditsByPair = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c existingCredit : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            softCreditsByPair.put(
                pairKey(existingCredit.npsp__Opportunity__c, existingCredit.npsp__Contact__c),
                existingCredit
            );
        }

        // ------------------------------------------------------------------
        // Validate the whole call before any DML.
        // ------------------------------------------------------------------
        List<String> errors = new List<String>();
        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest request = requests[i];
            Opportunity opportunity = opportunitiesById.get(request.opportunityId);

            if (opportunity == null) {
                errors.add('Request at index ' + i + ': Opportunity ' + request.opportunityId +
                           ' does not exist or is not visible.');
                continue;
            }

            if (opportunity.npsp__Primary_Contact__c == request.contactId) {
                errors.add('Request at index ' + i + ': Contact ' + request.contactId +
                           ' is the primary contact (npsp__Primary_Contact__c) of Opportunity ' +
                           request.opportunityId + ' and cannot receive a partial soft credit.');
            }

            if (request.amount == null) {
                errors.add('Request at index ' + i + ': amount must not be null.');
            } else if (request.amount <= 0) {
                errors.add('Request at index ' + i + ': amount must be positive (got ' +
                           request.amount + ').');
            } else if (opportunity.Amount != null && request.amount > opportunity.Amount) {
                errors.add('Request at index ' + i + ': amount ' + request.amount +
                           ' is greater than the opportunity amount (' + opportunity.Amount +
                           ') of Opportunity ' + request.opportunityId + '.');
            }

            if (request.role == null || request.role.trim().isEmpty()) {
                errors.add('Request at index ' + i + ': role must not be blank.');
            }
        }

        if (!errors.isEmpty()) {
            throw new SoftCreditException(
                'SoftCreditService validation failed; no records were changed. ' +
                String.join(errors, ' '));
        }

        // ------------------------------------------------------------------
        // Prepare contact role changes:
        //   - existing role for the pair: rename it to the requested role
        //     (covers the NPSP "Household Member" role case);
        //   - no existing role: create one with the requested role.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> contactRolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> contactRolesToInsert = new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String pair = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRolesByPair.get(pair);

            if (contactRole == null) {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role,
                    IsPrimary = false
                );
                contactRolesToInsert.add(contactRole);
                contactRolesByPair.put(pair, contactRole);
            } else if (contactRole.Role != request.role) {
                contactRole.Role = request.role;
                contactRolesToUpdate.add(contactRole);
            }
        }

        // DML 1/2: contact role updates and inserts (guarded so empty
        // collections do not consume limit headroom). Inserts must happen
        // before the partial soft credits are written so new roles have Ids.
        if (!contactRolesToUpdate.isEmpty()) {
            update contactRolesToUpdate;
        }
        if (!contactRolesToInsert.isEmpty()) {
            insert contactRolesToInsert;
        }

        // ------------------------------------------------------------------
        // Prepare partial soft credit changes:
        //   - existing soft credit for the pair: update amount, role name and
        //     the linked contact role Id;
        //   - none: create one linked to the (possibly new) contact role.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> softCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String pair = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRolesByPair.get(pair);
            npsp__Partial_Soft_Credit__c softCredit = softCreditsByPair.get(pair);

            if (softCredit == null) {
                softCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId,
                    npsp__Amount__c = request.amount,
                    npsp__Role_Name__c = request.role,
                    npsp__Contact_Role_ID__c = contactRole.Id
                );
                softCreditsToInsert.add(softCredit);
            } else {
                softCredit.npsp__Amount__c = request.amount;
                softCredit.npsp__Role_Name__c = request.role;
                softCredit.npsp__Contact_Role_ID__c = contactRole.Id;
                softCreditsToUpdate.add(softCredit);
            }
        }

        // DML 3/4: partial soft credit inserts and updates.
        if (!softCreditsToInsert.isEmpty()) {
            insert softCreditsToInsert;
        }
        if (!softCreditsToUpdate.isEmpty()) {
            update softCreditsToUpdate;
        }
    }

    /** Stable composite key for an (Opportunity, Contact) pair within this call. */
    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '-' + String.valueOf(contactId);
    }
}
