/**
 * @description Service for converting an open NPSP donation (pledge) into an
 *              equal monthly installment plan via its npe01__OppPayment__c records.
 *
 *              Paid and written-off payments are treated as history and left
 *              untouched. All other payments are deleted and replaced by
 *              numberOfPayments equal unpaid payments, scheduled monthly from
 *              firstPaymentDate. The last payment absorbs any rounding
 *              remainder so the schedule sums exactly to the outstanding
 *              amount.
 *
 *              All validations run before any DML, and both the delete and the
 *              insert happen in the same transaction, so a failure anywhere
 *              leaves the data unchanged.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    private static final Integer SCALE = 2; // currency amounts are precise to the cent

    /**
     * @description Replaces the opportunity's open (unpaid, not written-off)
     *              payments with an equal monthly installment schedule.
     * @param opportunityId    Id of the (open) Opportunity to reschedule.
     * @param numberOfPayments Number of installments to create. Must be >= 1.
     * @param firstPaymentDate Scheduled date of the first installment; each
     *                         subsequent installment is one month later.
     * @return The inserted payments, in schedule order.
     * @throws PaymentPlanException If numberOfPayments is null or < 1, the
     *                              opportunity does not exist or is closed, or
     *                              the outstanding amount is not greater than
     *                              zero. Nothing is modified in those cases.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {

        // ---- Input validation (before any DML) -------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }

        Opportunity opp;
        try {
            opp = [
                SELECT Id, Amount, IsClosed
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];
        } catch (QueryException qe) {
            throw new PaymentPlanException('Opportunity not found: ' + qe.getMessage());
        }

        if (opp == null) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        // ---- Analyze existing payments --------------------------------------
        // Paid or written-off payments are history: keep them and subtract
        // their amounts from the outstanding balance. Everything else gets
        // replaced.
        Decimal outstanding = opp.Amount == null ? 0 : opp.Amount;
        List<Id> paymentIdsToDelete = new List<Id>();

        for (npe01__OppPayment__c payment : [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ]) {
            Boolean isHistory = payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true;
            if (isHistory) {
                outstanding -= payment.npe01__Payment_Amount__c == null ? 0 : payment.npe01__Payment_Amount__c;
            } else {
                paymentIdsToDelete.add(payment.Id);
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // ---- Build the installment schedule ---------------------------------
        // Each installment is the outstanding amount divided by the number of
        // payments, rounded DOWN to the cent. The last installment absorbs the
        // remainder so the schedule sums exactly to the outstanding amount.
        Decimal installmentAmount = (outstanding / numberOfPayments).setScale(SCALE, RoundingMode.DOWN);
        Decimal scheduledToDate = installmentAmount * (numberOfPayments - 1);
        Decimal lastInstallmentAmount = outstanding - scheduledToDate;

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            newPayments.add(
                new npe01__OppPayment__c(
                    npe01__Opportunity__c   = opportunityId,
                    npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastInstallmentAmount : installmentAmount,
                    npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                    npe01__Paid__c           = false,
                    npe01__Written_Off__c    = false
                )
            );
        }

        // ---- DML -------------------------------------------------------------
        // Delete and insert run in the same transaction: if either fails, the
        // whole operation rolls back and nothing is changed.
        if (!paymentIdsToDelete.isEmpty()) {
            delete paymentIdsToDelete;
        }
        insert newPayments;

        return newPayments;
    }
}
