/**
 * @description Service for recording gifts (donations that have already been received)
 * in an NPSP org using the Household Account model and NPSP Payments.
 *
 * Design notes:
 * - With the Household Account model, the household account of a contact is simply
 *   the contact's AccountId, so the gift is credited to Contact.AccountId.
 * - NPSP automatically creates an Opportunity Contact Role for every household member
 *   and an NPSP Payment for every Closed Won opportunity. To guarantee the exact end
 *   state required here (one role per household member, exactly one paid payment),
 *   this service:
 *     1. Suppresses NPSP's automatic payment creation
 *        (npe01__Do_Not_Automatically_Create_Payment__c) and inserts the single
 *        payment itself, reconciling against any payment NPSP (or other automation)
 *        created anyway so there is never more than one payment.
 *     2. Reconciles Opportunity Contact Roles after insert: ensures each household
 *        member has exactly one role (Donor for the primary contact, Household Member
 *        for everyone else) and removes duplicates or roles for non-household contacts.
 * - All DML operates on collections and is bulk-safe.
 */
public with sharing class GiftService {

    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String DONOR_ROLE = 'Donor';
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';

    /**
     * @description Records a gift that has already been received from a contact.
     * @param contactId Id of the donating contact. Must reference an existing Contact.
     * @param amount    Gift amount. Must be a positive number.
     * @param giftDate  Date the gift was received/closed. If null, defaults to today.
     * @return Id of the created Opportunity.
     * @throws IllegalArgumentException if the contact does not exist, or amount is
     *                                  null, zero or negative.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInput(contactId, amount);
        Date effectiveGiftDate = giftDate != null ? giftDate : System.today();

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' has no household account; the gift cannot be credited.'
            );
        }

        // Household Account model: every member of the household shares the same AccountId.
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        Opportunity gift = new Opportunity(
            Name = buildGiftName(donor, effectiveGiftDate),
            StageName = CLOSED_WON_STAGE,
            CloseDate = effectiveGiftDate,
            Amount = amount,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            // We create the single payment ourselves; suppress NPSP auto-payment
            // creation to avoid duplicate payments.
            npe01__Do_Not_Automatically_Create_Payment__c = true
        );
        insert gift;

        reconcileContactRoles(gift.Id, donor.Id, householdMembers);
        reconcilePayments(gift.Id, amount, effectiveGiftDate);

        return gift.Id;
    }

    /**
     * @description Validates the incoming arguments.
     */
    private static void validateInput(Id contactId, Decimal amount) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId must not be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a positive number.');
        }
    }

    /**
     * @description Builds the required opportunity name:
     *              "<FirstName> <LastName> Donation <yyyy-MM-dd>", zero-padded,
     *              locale-independent (Date.format() is locale sensitive, so we format manually).
     */
    private static String buildGiftName(Contact donor, Date giftDate) {
        String firstName = String.isBlank(donor.FirstName) ? '' : donor.FirstName.trim();
        String lastName = String.isBlank(donor.LastName) ? '' : donor.LastName.trim();
        String contactName = (firstName + ' ' + lastName).trim();
        return contactName + ' Donation ' + formatDate(giftDate);
    }

    private static String formatDate(Date d) {
        return d.year() + '-' + pad2(d.month()) + '-' + pad2(d.day());
    }

    private static String pad2(Integer value) {
        return (value < 10 ? '0' : '') + value;
    }

    /**
     * @description Guarantees the required contact role state on the gift:
     *              - the donor is primary with the "Donor" role;
     *              - every other household member has exactly one "Household Member" role;
     *              - no contact has more than one role on the opportunity.
     *              Handles the roles NPSP (or other automation) may already have created.
     */
    private static void reconcileContactRoles(Id opportunityId, Id primaryContactId, List<Contact> householdMembers) {
        Map<Id, OpportunityContactRole> existingRoleByContact = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole existing : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ]) {
            if (existingRoleByContact.containsKey(existing.ContactId)) {
                // Duplicate role for the same contact: never allowed.
                rolesToDelete.add(existing);
            } else {
                existingRoleByContact.put(existing.ContactId, existing);
            }
        }

        // Desired role per household member.
        Map<Id, String> desiredRoleByContact = new Map<Id, String>();
        for (Contact member : householdMembers) {
            desiredRoleByContact.put(
                member.Id,
                member.Id == primaryContactId ? DONOR_ROLE : HOUSEHOLD_MEMBER_ROLE
            );
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        for (Id contactId : desiredRoleByContact.keySet()) {
            Boolean shouldBePrimary = contactId == primaryContactId;
            String desiredRole = desiredRoleByContact.get(contactId);
            OpportunityContactRole existing = existingRoleByContact.get(contactId);
            if (existing != null) {
                if (existing.Role != desiredRole || existing.IsPrimary != shouldBePrimary) {
                    existing.Role = desiredRole;
                    existing.IsPrimary = shouldBePrimary;
                    rolesToUpdate.add(existing);
                }
            } else {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = contactId,
                    Role = desiredRole,
                    IsPrimary = shouldBePrimary
                ));
            }
        }

        // Remove roles belonging to contacts that are not members of this household.
        for (Id leftoverContactId : existingRoleByContact.keySet()) {
            if (!desiredRoleByContact.containsKey(leftoverContactId)) {
                rolesToDelete.add(existingRoleByContact.get(leftoverContactId));
            }
        }

        // Delete first so there is never a transient duplicate-primary state.
        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    /**
     * @description Guarantees exactly one payment on the gift: paid, for the full amount,
     *              with payment and scheduled dates equal to the gift date.
     *              If automation created a payment anyway, it is corrected (and any
     *              extras removed) rather than adding a second payment.
     */
    private static void reconcilePayments(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate, Id
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c payment = existingPayments[0];
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;

            if (existingPayments.size() > 1) {
                existingPayments.remove(0);
                delete existingPayments;
            }
        }
    }
}
