/**
 * @description  Imports family links from an external student system into NPSP.
 *
 *               The org uses the NPSP Relationships object (npe4__Relationship__c)
 *               with the "List Setting" reciprocal method. Under that method, the
 *               NPSP Relationships trigger automatically creates and links the
 *               reciprocal relationship record whenever a relationship is
 *               inserted, resolving the reciprocal type through the
 *               npe4__Relationship_Lookup__c settings.
 *
 *               For the `Parent` type the lookup is configured as:
 *                   Male    -> Son
 *                   Female  -> Daughter
 *                   Neutral -> Child
 *               so inserting a single child -> parent record of type `Parent`
 *               results in exactly one record in each direction:
 *                   child   : Parent            (inserted here)
 *                   parent  : Son/Daughter/Child (created and linked by NPSP,
 *                                          based on the parent's gender)
 *
 *               Best practice when importing NPSP relationships is therefore to
 *               insert only ONE side of each pair and let NPSP create the
 *               reciprocal. Inserting both sides ourselves would cause NPSP to
 *               generate duplicates (and would additionally require a Contact
 *               gender query plus a Relationship Lookup query, breaking the
 *               strict 1-SOQL / 1-DML budget for this import).
 */
public inherited sharing class FamilyService {

    /** NPSP relationship type used from the child's perspective. */
    private static final String TYPE_PARENT = 'Parent';

    /** NPSP relationship status required by the import. */
    private static final String STATUS_CURRENT = 'Current';

    /**
     * @description Records that each parent (map value) is the `Parent` of the
     *              child (map key), with status `Current`.
     *
     *              Guarantees:
     *              - Exactly one relationship record in each direction per pair
     *                (this code inserts the child->parent record; NPSP's
     *                reciprocal machinery creates the parent->child record).
     *              - Pairs for which ANY relationship already exists between
     *                the two contacts (in either direction, of any type or
     *                status) are skipped, making the import safely re-runnable.
     *              - Degenerate pairs (null key/value, or a contact paired with
     *                itself) are ignored, as are the same two contacts supplied
     *                twice in opposite directions within one call.
     *              - Null or empty input does nothing.
     *              - Uses at most 1 SOQL query and 1 DML statement of its own
     *                for any input size (200 pairs in a single call is well
     *                within budget; NPSP's own trigger DML is not charged here).
     *
     * @param parentIdByChildId Map of child Contact Id -> parent Contact Id.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input: nothing to do.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ---- 1. Validate the requested pairs (no SOQL/DML yet). -------------
        Set<Id> childIds  = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                // Ignore unusable pairs: a contact cannot be their own parent.
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
        }

        if (childIds.isEmpty()) {
            return; // Nothing usable was requested; avoid spending the query.
        }

        // ---- 2. Exactly one SOQL query: every existing relationship that ----
        //         connects any requested child to any requested parent, in
        //         either direction. Rows may belong to pairs other than the
        //         requested ones (cross matches between the two Id sets), so
        //         results are normalized into pair keys and matched exactly.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c existingRel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            existingPairKeys.add(
                pairKey(existingRel.npe4__Contact__c, existingRel.npe4__RelatedContact__c)
            );
        }

        // ---- 3. Build the child -> parent records to insert. ---------------
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        Set<String> pairsHandledThisCall = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);

            // Skip if a relationship already exists between the two contacts
            // in either direction (re-run safety), or if this exact pair of
            // contacts was already handled in this call (e.g. the map contains
            // both A -> X and X -> A, which describe the same family link).
            if (existingPairKeys.contains(key) || !pairsHandledThisCall.add(key)) {
                continue;
            }

            relationshipsToInsert.add(
                new npe4__Relationship__c(
                    npe4__Contact__c        = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c           = TYPE_PARENT,
                    npe4__Status__c         = STATUS_CURRENT
                )
            );
        }

        // ---- 4. Exactly one DML statement. NPSP's Relationships trigger ------
        //         (List Setting reciprocal method) then creates the reciprocal
        //         parent -> Son/Daughter/Child record per the Relationship
        //         Lookup and links both records via npe4__ReciprocalRelationship__c.
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    /**
     * @description Direction-independent key for a pair of Contacts, so a
     *              relationship between A and B is detected regardless of which
     *              contact occupies npe4__Contact__c vs npe4__RelatedContact__c.
     *
     * @param firstContactId  One contact of the pair.
     * @param secondContactId The other contact of the pair.
     * @return A deterministic key for the unordered pair.
     */
    private static String pairKey(Id firstContactId, Id secondContactId) {
        String first  = String.valueOf(firstContactId);
        String second = String.valueOf(secondContactId);
        return first.compareTo(second) < 0 ? first + ':' + second : second + ':' + first;
    }
}
