/**
 * NPSP Table-Driven Trigger Management (TDTM) handler for Opportunity.
 *
 * Purpose
 * -------
 * When a major gift is created, or an existing opportunity first becomes a
 * major gift, create a single high-priority follow-up Task for the opportunity
 * owner so they can make a thank-you call.
 *
 * Qualification ("major gift")
 * ----------------------------
 * An Opportunity qualifies when it is Closed Won (IsWon = true, which is set
 * automatically for the "Closed Won" stage) AND Amount >= 5000.
 *
 *   - AfterInsert:  the incoming record qualifies  -> create the Task.
 *   - AfterUpdate:  the record qualifies now AND did NOT qualify before
 *                   (i.e. it was not both Closed Won and >= 5000 previously)
 *                   -> create the Task.
 *   - Editing a gift that already qualified does NOT create another Task,
 *     because the "before" record already qualified (and as a belt-and-braces
 *     guard, a single SOQL also skips Opportunities that already carry the
 *     thank-you Task).
 *
 * Registration (performed by the admin, no code needed)
 * -----------------------------------------------------
 * NPSP Settings > Trigger Configuration (Trigger_Handler__c):
 *   Class .......... OPP_MajorGiftFollowUp_TDTM
 *   Object ......... Opportunity
 *   Trigger Action . AfterInsert;AfterUpdate
 *   Load Order ..... 5
 *   Asynchronous ... false (leave the "Class runs asynchronously" flag off)
 *
 * NPSP's TDTM dispatcher (the npsp.TDTM_TriggerHandler trigger plus
 * npsp.TDTM_TrigHandler) queries the Trigger_Handler__c records and only
 * invokes handlers whose record is Active. Deactivating the Trigger Handler
 * record therefore stops this handler completely - no Apex trigger is created
 * here and no code change is needed to switch the automation off.
 *
 * Governance
 * ----------
 * Bulk-safe for 200 Opportunities in one transaction:
 *   - 0 queries to read Opportunity data (trigger context provides all fields).
 *   - Exactly 1 SOQL query (duplicate-Task guard, bulkified with an IN clause).
 *   - Exactly 1 DML statement of its own (one Database.insert of all Tasks).
 *
 * The class runs in trigger context; it is declared `without sharing` so the
 * duplicate-Task guard and the Task inserts behave consistently for
 * opportunities owned by any user.
 */
public without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String TASK_SUBJECT  = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS   = 'Not Started';

    private static final Decimal MAJOR_GIFT_MIN_AMOUNT = 5000;
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;

    /**
     * TDTM entry point, invoked by npsp.TDTM_TrigHandler for the registered
     * trigger actions (AfterInsert;AfterUpdate). Any records the framework
     * should persist can be returned via the DmlWrapper; here the Tasks are
     * inserted directly (one DML statement) so this handler stays fully
     * self-contained, and an empty wrapper is returned.
     *
     * @param newList       the incoming Opportunity records (trigger new list)
     * @param oldList       the prior Opportunity records (trigger old list;
     *                      null/empty on insert), index-aligned with newList
     * @param triggerAction the TDTM action being processed
     * @param objResult     describe of the object being processed (Opportunity)
     * @return an (empty) DmlWrapper; the Task DML is performed directly below
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // Defensive guard: only run for the registered after-insert/after-update
        // actions. (NPSP's dispatcher also only invokes Active Trigger Handler
        // records, so deactivating the record stops this handler entirely.)
        if (triggerAction != npsp.TDTM_Runnable.Action.afterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.afterUpdate) {
            return wrapper;
        }

        // Respect FLS/create access on Task for the running context.
        if (!Schema.sObjectType.Task.isCreateable()) {
            return wrapper;
        }

        List<Opportunity> newOpps = (List<Opportunity>) newList;
        List<Opportunity> oldOpps = oldList == null ? new List<Opportunity>() : (List<Opportunity>) oldList;

        // Step 1 (no SOQL): identify Opportunities that just became qualified.
        Set<Id> newlyQualifiedIds = new Set<Id>();
        for (Integer i = 0; i < newOpps.size(); i++) {
            Opportunity newOpp = newOpps[i];
            Opportunity oldOpp = (triggerAction == npsp.TDTM_Runnable.Action.afterUpdate && i < oldOpps.size())
                ? oldOpps[i]
                : null;

            if (isQualified(newOpp) && !wasQualified(oldOpp)) {
                newlyQualifiedIds.add(newOpp.Id);
            }
        }

        if (newlyQualifiedIds.isEmpty()) {
            return wrapper;
        }

        // Step 2 (1 SOQL, bulkified): skip Opportunities that already carry the
        // thank-you Task (e.g. created by a previous run while the handler was
        // re-activated, or by another process) so we never duplicate.
        Set<Id> oppIdsWithExistingTask = new Set<Id>();
        for (Task existingTask : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :newlyQualifiedIds
              AND Subject = :TASK_SUBJECT
        ]) {
            oppIdsWithExistingTask.add(existingTask.WhatId);
        }

        // Step 3: build one Task per newly qualified Opportunity.
        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : newOpps) {
            if (!newlyQualifiedIds.contains(opp.Id) || oppIdsWithExistingTask.contains(opp.Id)) {
                continue;
            }

            tasksToInsert.add(new Task(
                Subject      = TASK_SUBJECT,
                Priority     = TASK_PRIORITY,
                Status       = TASK_STATUS,
                WhatId       = opp.Id,
                WhoId        = opp.npsp__Primary_Contact__c, // may be null - allowed
                OwnerId      = opp.OwnerId,                  // the Opportunity owner
                ActivityDate = (opp.CloseDate == null)
                                ? null
                                : opp.CloseDate + FOLLOW_UP_OFFSET_DAYS
            ));
        }

        // Step 4 (1 DML of its own): insert all Tasks in one statement. Partial
        // success keeps one bad record from rolling back the whole batch.
        if (!tasksToInsert.isEmpty()) {
            Database.insert(tasksToInsert, false);
        }

        return wrapper;
    }

    /**
     * True when the Opportunity is currently a qualifying major gift:
     * Closed Won (IsWon) with Amount >= 5000. Null Amount never qualifies.
     */
    private static Boolean isQualified(Opportunity opp) {
        return opp.IsWon
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_MIN_AMOUNT;
    }

    /**
     * True when the pre-change version of the Opportunity already qualified.
     * On insert there is no prior version, so this is always false and a
     * qualifying insert always produces a Task. On update, a gift that was
     * already qualified does not produce a second Task.
     */
    private static Boolean wasQualified(Opportunity oldOpp) {
        return oldOpp != null && isQualified(oldOpp);
    }
}
