/**
 * RecordAccessService
 *
 * Returns the subset of the given record IDs that the running user is allowed
 * to edit, as reported by the UserRecordAccess object (HasEditAccess).
 *
 * UserRecordAccess already accounts for every factor that governs edit access:
 *   - object-level permissions (CRUD, e.g. Editable on the sObject describe)
 *   - ownership
 *   - role hierarchy
 *   - sharing rules / manual shares / account & contact team sharing
 *   - View All Data / Modify All Data
 *   - View All / Modify All object permissions
 *   - parent sharing (e.g. contacts/cases/opportunities inheriting from account)
 *
 * Bulkification strategy:
 *   - UserRecordAccess must be filtered by UserId and RecordId. RecordId
 *     supports the IN operator, so we query in chunks rather than one query
 *     per record.
 *   - The chunk size is 100 IDs per query. With a hard cap of 20 queries this
 *     covers the documented maximum input of 2,000 IDs (100 * 20 = 2,000) and
 *     stays well within Salesforce's per-transaction SOQL limit.
 *   - If a caller nevertheless passes more than 2,000 IDs, the extra IDs are
 *     not queried (they would blow the governor limit); they simply are not
 *     included in the result, mirroring the behavior of an inaccessible record.
 *
 * Notes on semantics:
 *   - Only IDs that come back with HasEditAccess = true are returned. Records
 *     the user cannot even read do not yield an edit-accessible row and are
 *     therefore naturally excluded.
 *   - Duplicate and null IDs in the input are tolerated.
 *   - A null or empty input yields an empty set, never null.
 *   - The method is safe to call from a "with sharing" or "without sharing"
 *     context: UserRecordAccess is evaluated for the running user regardless
 *     of the class sharing mode, and this class is declared "with sharing".
 */
public with sharing class RecordAccessService {

    /** Number of RecordIds bound into a single UserRecordAccess query. */
    @TestVisible
    private static final Integer CHUNK_SIZE = 100;

    /** Maximum number of UserRecordAccess queries per invocation. */
    @TestVisible
    private static final Integer MAX_QUERIES = 20;

    /**
     * Returns the subset of recordIds that the running user can edit.
     *
     * @param recordIds candidate record IDs, possibly from multiple objects,
     *                  possibly containing duplicates or nulls; may be null
     * @return the editable subset (empty set, never null)
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        // Guard clause: null or empty input always yields an empty set.
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Deduplicate and drop nulls so we never bind them into a query.
        Set<Id> uniqueIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                uniqueIds.add(recordId);
            }
        }
        if (uniqueIds.isEmpty()) {
            return editable;
        }

        List<Id> idList = new List<Id>(uniqueIds);
        Integer maxIds = CHUNK_SIZE * MAX_QUERIES; // 2,000 by default

        for (Integer offset = 0;
             offset < idList.size() && offset < maxIds;
             offset += CHUNK_SIZE) {

            Integer end = Math.min(offset + CHUNK_SIZE, idList.size());
            List<Id> chunk = idList.subList(offset, end);

            // One query per chunk; ~100 binds keeps the query string and the
            // bind-variable footprint well within limits. Filter on the
            // running user's id — required by UserRecordAccess.
            for (UserRecordAccess access : [
                    SELECT RecordId, HasEditAccess
                    FROM UserRecordAccess
                    WHERE UserId = :UserInfo.getUserId()
                      AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
