/**
 * @description Creates an onboarding Task for the account owner when a new
 *              Account is created with Type 'Customer - Direct' or
 *              'Customer - Channel'. Registered via Trigger_Action__mdt
 *              (DeveloperName TA_Account_CreateOnboardingTask, After Insert on
 *              Account, Order 10). Runs in the after insert context so the
 *              Account Ids are available; tasks are collected and inserted in
 *              a single DML statement, and no DML is issued when no account
 *              qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    @TestVisible
    private static final Set<String> ONBOARDING_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    @TestVisible
    private static final Integer DUE_IN_DAYS = 7;

    /**
     * @description Called by the Trigger Actions Framework after Account
     *              insert. Builds one onboarding Task per qualifying account
     *              and inserts them all with a single DML statement.
     * @param triggerNew the newly inserted Accounts
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Account> newAccounts = (List<Account>) triggerNew;
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Task> onboardingTasks = new List<Task>();
        for (Account account : newAccounts) {
            if (isQualifyingType(account.Type)) {
                onboardingTasks.add(buildOnboardingTask(account));
            }
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }

    /**
     * @description Determines whether the given Account Type qualifies for an
     *              onboarding task.
     * @param accountType the Account's Type value (may be null)
     * @return true when the type is a customer type that requires onboarding
     */
    private Boolean isQualifyingType(String accountType) {
        return accountType != null && ONBOARDING_TYPES.contains(accountType);
    }

    /**
     * @description Builds the onboarding Task for a single Account.
     * @param account the newly created Account
     * @return an in-memory Task assigned to the account's owner, due 7 days
     *         from today
     */
    private Task buildOnboardingTask(Account account) {
        return new Task(
            Subject = 'Onboard new customer',
            WhatId = account.Id,
            OwnerId = account.OwnerId,
            ActivityDate = Date.today().addDays(DUE_IN_DAYS),
            Status = 'Not Started',
            Priority = 'Normal'
        );
    }
}
```

