 *
 * Design notes:
 *  - Account trigger actions (Trigger Actions Framework) are suppressed for the
 *    duration of the Account/Contact DML via TriggerBase.bypass on the whole
 *    Account sObject, because Account territory-recalculation automation must
 *    not run for ownership-only changes. The bypass is restored in a finally
 *    block so Account automation behaves normally for the rest of the
 *    transaction, whether reassign succeeds or throws.
 *    If the caller had already bypassed Account before calling this method,
 *    we do not clear their bypass (we only clear what we set).
 *  - Contacts are updated normally so all Contact trigger actions run.
 *  - Bulk-safe for up to 200 (or more) accounts: exactly one SOQL query
 *    (Contacts of the given accounts) and two DML statements
 *    (one Account update, one Contact update).
 *  - DML is all-or-none (Apex default); any exception propagates to the
 *    caller unchanged.
 */
public inherited sharing class AccountOwnershipService {

    /**
     * @description Sets OwnerId on the given Accounts and on all Contacts of
     *              those Accounts, bypassing Account trigger actions only.
     * @param accountIds Account Ids whose ownership changes. Null / empty
     *        entries are ignored.
     * @param newOwnerId Id of the User (or queue) that becomes the owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // 1) Build the Account update payload (no SOQL needed - DML by Id).
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountsToUpdate.add(new Account(
                    Id = accountId,
                    OwnerId = newOwnerId
                ));
            }
        }
        if (accountsToUpdate.isEmpty()) {
            return;
        }

        // 2) Query all Contacts of the given Accounts (SOQL #1 of 1) and
        //    build the Contact update payload.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : [
            SELECT Id, OwnerId, AccountId
            FROM Contact
            WHERE AccountId IN :accountsToUpdate
        ]) {
            contactsToUpdate.add(new Contact(
                Id = contact.Id,
                OwnerId = newOwnerId
            ));
        }

        // 3) Suppress all Account trigger actions for this ownership change.
        //    Respect a pre-existing bypass from the caller: only clear the
        //    bypass if this method set it.
        Schema.SObjectType accountType = Schema.Account.getSObjectType();
        Boolean bypassPreExisted = TriggerBase.isBypassed(accountType);
        if (!bypassPreExisted) {
            TriggerBase.bypass(accountType);
        }

        try {
            // DML #1 of 2: Accounts (all-or-none; Contact triggers unaffected
            // by the Account bypass). Account trigger actions do not run.
            update accountsToUpdate;

            // DML #2 of 2: Contacts (all-or-none; Contact trigger actions run
            // normally for every Contact).
            update contactsToUpdate;
        } finally {
            // Restore Account automation regardless of success/failure, so
            // the rest of the transaction behaves normally.
            if (!bypassPreExisted) {
                TriggerBase.clearBypass(accountType);
            }
        }
    }
}
