/**
 * DML-less tests for the before-update Trigger Actions Framework action
 * TA_Opportunity_GuardAmountDecrease.
 *
 * Following the TAF recommended testing pattern, no DML and no SOQL are used:
 * triggerNew / triggerOld lists are built in memory, records are given fake Ids
 * via TriggerTestUtility.getFakeId(...), and the action's beforeUpdate context
 * method is invoked directly.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * Builds a new Opportunity with a fake Id and the given Amount.
     */
    private static Opportunity newOpp(Decimal amount) {
        Opportunity opp = new Opportunity(
            Id = TriggerTestUtility.getFakeId(Opportunity.SObjectType),
            Amount = amount
        );
        return opp;
    }

    /**
     * Runs the action's beforeUpdate context method directly on in-memory lists.
     */
    private static void runBeforeUpdate(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(newOpps, oldOpps);
    }

    /**
     * Asserts that the record has exactly one error and that its message equals
     * the action's ERROR_MESSAGE constant.
     */
    private static void assertSingleGuardError(Opportunity opp) {
        System.assert(opp.hasErrors(), 'Expected the record to have errors but it had none.');
        System.assertEquals(
            1,
            opp.getErrors().size(),
            'Expected exactly one error on the record.'
        );
        System.assertEquals(
            ERROR_MESSAGE,
            opp.getErrors()[0].getMessage(),
            'The error message did not match ERROR_MESSAGE.'
        );
    }

    /**
     * Asserts that the record carries no errors at all.
     */
    private static void assertNoErrors(Opportunity opp) {
        System.assert(
            !opp.hasErrors(),
            'Expected no errors on the record but found: ' +
                (opp.hasErrors() ? opp.getErrors()[0].getMessage() : '')
        );
    }

    @IsTest
    static void testReductionOfMoreThanHalfIsRejected() {
        Opportunity oldOpp = newOpp(1000);
        Opportunity newOpp = newOpp(499);

        Test.startTest();
        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        Test.stopTest();

        assertSingleGuardError(newOpp);
    }

    @IsTest
    static void testReductionOfExactlyHalfIsAccepted() {
        Opportunity oldOpp = newOpp(1000);
        Opportunity newOpp = newOpp(500);

        Test.startTest();
        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        Test.stopTest();

        assertNoErrors(newOpp);
    }

    @IsTest
    static void testIncreaseIsAccepted() {
        Opportunity oldOpp = newOpp(1000);
        Opportunity newOpp = newOpp(2500);

        Test.startTest();
        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        Test.stopTest();

        assertNoErrors(newOpp);
    }

    @IsTest
    static void testNullPreviousAmountIsAcceptedWithoutException() {
        Opportunity oldOpp = newOpp(null);
        Opportunity newOpp = newOpp(10);

        Test.startTest();
        // Must complete without throwing (no NullPointerException on the null previous Amount).
        runBeforeUpdate(new List<Opportunity>{ newOpp }, new List<Opportunity>{ oldOpp });
        Test.stopTest();

        assertNoErrors(newOpp);
    }

    @IsTest
    static void testMixedBatchOnlyViolatingRecordsGetErrors() {
        // (previous, new) pairs; expectedError tells which records must be rejected.
        List<Opportunity> newOpps = new List<Opportunity>();
        List<Opportunity> oldOpps = new List<Opportunity>();

        // Reduces by more than half -> must error.
        Opportunity violating1 = newOpp(499);
        // Increases -> must pass.
        Opportunity passing1 = newOpp(2000);
        // Reduces by exactly half -> must pass.
        Opportunity passing2 = newOpp(500);
        // Reduces by more than half -> must error.
        Opportunity violating2 = newOpp(100);
        // Unchanged -> must pass.
        Opportunity passing3 = newOpp(750);

        newOpps.addAll(new List<Opportunity>{ violating1, passing1, passing2, violating2, passing3 });
        oldOpps.addAll(new List<Opportunity>{
            newOpp(1000), newOpp(1000), newOpp(1000), newOpp(1000), newOpp(750)
        });

        Test.startTest();
        runBeforeUpdate(newOpps, oldOpps);
        Test.stopTest();

        assertSingleGuardError(violating1);
        assertNoErrors(passing1);
        assertNoErrors(passing2);
        assertSingleGuardError(violating2);
        assertNoErrors(passing3);
    }
}
```

**Notes on the implementation**

- **No DML / no SOQL:** every test constructs `triggerNew` and `triggerOld` in memory and invokes `new TA_Opportunity_GuardAmountDecrease().beforeUpdate(...)` directly — the TAF-recommended pattern for unit-testing individual actions without going through the trigger handler.
- **Fake Ids:** `TriggerTestUtility.getFakeId(Opportunity.SObjectType)` (part of the installed package, `@IsTest` visible) supplies distinct, validly formatted Opportunity Ids so the action's internal `Map<Id, Opportunity>(triggerOld)` lookup works. Each record gets its own fresh fake Id — even the `old` record — so the new/old maps key correctly and no two rows collide.
- **SObject error API:** assertions use `hasErrors()` / `getErrors()`, never try/catch, since `addError` on in-memory records surfaces through that API. `assertSingleGuardError` checks both the error count (exactly one) and the message equality against the `@TestVisible` `ERROR_MESSAGE` constant, so any change in the guard's threshold, count, or message fails the suite.
- **Boundary precision:** case 2 (1000 → 500) pins the strict `<` comparison — the boundary case would catch an accidental `<=` regression.
- **Null safety:** case 4 verifies no exception is thrown when the old `Amount` is null, matching the action's explicit null guard.
- **Bulk case:** case 5 exercises a single `beforeUpdate` call with five records and asserts errors land on exactly the two violating rows and nowhere else, confirming per-row error assignment in a mixed batch.

