/**
 * Trigger Actions Framework action for Contact.
 *
 * Business rule: two Contacts of the same Account may not share an email address
 * (compared case-insensitively). Contacts without an Account or without an Email
 * are not checked.
 *
 * Runs in the before insert and before update contexts so that offending records
 * get a record-level error (addError), which allows partial saves: valid records
 * in the same save commit, invalid ones are rejected individually.
 *
 * Bulk-safe: at most one SOQL query per trigger execution (chunk size 200).
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    /**
     * Before insert: every contact with an Account and an Email is checked.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    /**
     * Before update: only contacts whose Email or AccountId changed are checked,
     * so pre-existing legacy duplicates do not block unrelated edits.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void validate(List<Contact> newContacts, List<Contact> oldContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }

        // Collect the records that must be checked, preserving trigger order so that
        // "first one in the list wins" is deterministic.
        List<Contact> candidates = new List<Contact>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact current = newContacts[i];
            if (current.AccountId == null || String.isBlank(current.Email)) {
                continue; // not subject to the rule
            }
            if (oldContacts != null) {
                Contact old = oldContacts[i];
                Boolean emailChanged = current.Email != old.Email;
                Boolean accountChanged = current.AccountId != old.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue; // unrelated edit: skip (legacy duplicates stay untouched)
                }
            }
            candidates.add(current);
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Build the single SOQL query: existing committed contacts that could conflict.
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> candidateIds = new Set<Id>();
        for (Contact candidate : candidates) {
            accountIds.add(candidate.AccountId);
            emails.add(candidate.Email);
            if (candidate.Id != null) {
                // On update, exclude the candidates themselves so a record can never
                // conflict with its own previously stored values.
                candidateIds.add(candidate.Id);
            }
        }

        String soql = 'SELECT AccountId, Email FROM Contact ' +
            'WHERE AccountId IN :accountIds AND Email IN :emails';
        if (!candidateIds.isEmpty()) {
            soql += ' AND Id NOT IN :candidateIds';
        }

        // SOQL string comparison on Email is case-insensitive, so this query finds
        // duplicates regardless of letter casing. Keys are normalized to lowercase
        // below for the in-batch comparison.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : Database.query(soql)) {
            existingKeys.add(String.valueOf(existing.AccountId) + '|' + existing.Email.toLowerCase());
        }

        // First occurrence of a key in this save is accepted, later ones are rejected.
        Set<String> keysSeenInBatch = new Set<String>();
        for (Contact candidate : candidates) {
            String key = String.valueOf(candidate.AccountId) + '|' + candidate.Email.toLowerCase();
            if (existingKeys.contains(key) || keysSeenInBatch.contains(key)) {
                candidate.addError(ERROR_MESSAGE);
            } else {
                keysSeenInBatch.add(key);
            }
        }
    }
}
