/**
 * @description Trigger Action that normalizes incoming Lead contact data so the
 *              values are clean on first save. Runs in the before insert context,
 *              which means the corrections happen before validation rules, duplicate
 *              rules and field history see the record, and no additional DML or SOQL
 *              is required.
 *
 *              - Email    : trimmed and lower-cased (null stays null).
 *              - Company  : trimmed.
 *              - LeadSource: defaulted to 'Web' when blank; existing values kept.
 *
 *              Registered via Trigger_Action__mdt 'TA_Lead_NormalizeContactInfo'
 *              on the Lead before insert context, Order 10.
 *
 *              Bulk-safe: operates purely in memory over the full trigger batch
 *              (200+ records), no DML, no SOQL, no recursion risk.
 *
 * @group       Trigger Actions Framework
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * @description Cleans Email, Company and LeadSource on every Lead in the batch
     *              before it is written to the database.
     * @param triggerNew The list of new Leads being inserted (up to 200 per chunk).
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject sobj : triggerNew) {
            Lead lead = (Lead) sobj;
            normalizeEmail(lead);
            trimCompany(lead);
            defaultLeadSource(lead);
        }
    }

    /**
     * @description Trims and lower-cases Email; a null Email remains null.
     */
    private void normalizeEmail(Lead lead) {
        String email = lead.Email;
        if (String.isBlank(email)) {
            // Keep null as null; also turns whitespace-only values into null.
            if (email != null) {
                lead.Email = null;
            }
            return;
        }
        lead.Email = email.trim().toLowerCase();
    }

    /**
     * @description Removes leading/trailing whitespace from Company.
     */
    private void trimCompany(Lead lead) {
        String company = lead.Company;
        if (company != null) {
            lead.Company = company.trim();
        }
    }

    /**
     * @description Sets LeadSource to 'Web' only when it is blank,
     *              preserving any value supplied by the source system.
     */
    private void defaultLeadSource(Lead lead) {
        if (String.isBlank(lead.LeadSource)) {
            lead.LeadSource = DEFAULT_LEAD_SOURCE;
        }
    }
}
