/**
 * @description Trigger Action for the Trigger Actions Framework (Mitch Spano, v0.3.4).
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's
 * Cases with IsClosed = false.
 *
 * Registered on Case in the after insert, after update, after delete and
 * after undelete contexts via Trigger_Action__mdt records.
 *
 * Design notes:
 * - The affected account set is gathered from trigger.new and trigger.old
 *   across all handled contexts (update moves therefore adjust both the old
 *   and the new account).
 * - The count is always recomputed from the database in a single aggregate
 *   query, so the action is correct for any combination of events (open or
 *   already closed inserts, closes, reopens, re-parenting, deletes,
 *   undeletes) regardless of which context fired.
 * - Accounts with no open cases get an explicit 0 (never blank), including
 *   accounts that lost their last open case.
 * - Limits per trigger execution: 1 SOQL on Account (current values),
 *   1 aggregate SOQL on Case, 1 DML on Account (only accounts whose value
 *   actually changed are written, so unrelated Account automation is not
 *   needlessly fired).
 * - Cases without an AccountId are ignored.
 * - Updating only Account rows cannot re-fire the Case trigger, so no
 *   recursion guard is required.
 */
public inherited sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert,
                   TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete,
                   TriggerAction.AfterUndelete {

    private final Set<Id> accountIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        collectIds((List<Case>) triggerNew, null);
        recalculate();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        collectIds((List<Case>) triggerNew, (List<Case>) triggerOld);
        recalculate();
    }

    public void afterDelete(List<SObject> triggerOld) {
        collectIds(null, (List<Case>) triggerOld);
        recalculate();
    }

    public void afterUndelete(List<SObject> triggerNew) {
        collectIds((List<Case>) triggerNew, null);
        recalculate();
    }

    /**
     * @description Adds the AccountId of every affected case (old and new
     *              values where available) to the working set. Cases without
     *              an account are ignored.
     */
    private void collectIds(List<Case> triggerNew, List<Case> triggerOld) {
        if (triggerNew != null) {
            for (Case c : triggerNew) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }
        if (triggerOld != null) {
            for (Case c : triggerOld) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }
    }

    /**
     * @description Recomputes the open case count for every affected account
     *              and updates only the accounts whose stored value differs.
     *              Uses at most 2 SOQL queries and 1 DML statement.
     */
    private void recalculate() {
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1 of 2: current stored values (null is treated as 0).
        Map<Id, Decimal> storedCounts = new Map<Id, Decimal>();
        for (Account acc : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            storedCounts.put(acc.Id, acc.FB_Open_Case_Count__c == null ? 0 : acc.FB_Open_Case_Count__c);
        }

        // Query 2 of 2: actual number of open cases per affected account.
        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId accId, COUNT(Id) openCount
                FROM Case
                WHERE IsClosed = false
                AND AccountId IN :accountIds
                GROUP BY AccountId
        ]) {
            openCounts.put((Id) ar.get('accId'), (Integer) ar.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Integer openCount = openCounts.containsKey(accountId) ? openCounts.get(accountId) : 0;
            Decimal storedCount = storedCounts.containsKey(accountId) ? storedCounts.get(accountId) : 0;
            if (openCount != storedCount) {
                accountsToUpdate.add(new Account(
                        Id = accountId,
                        FB_Open_Case_Count__c = openCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate; // 1 DML statement
        }
    }
}
