/**
 * @description After-update Trigger Action (Trigger Actions Framework 0.3.4) that writes an
 * audit trail for Opportunity Amount changes: for every Opportunity whose Amount differs from
 * its pre-update value, a completed Task with Subject 'Amount changed' is created on the record.
 *
 * Recursion handling:
 * The registered action TA_Opportunity_RoundAmount (Order__c 20) re-updates Opportunities in the
 * same transaction to round Amounts to whole units. That second DML re-runs this action, and in
 * that run the Amount legitimately differs from triggerOld (pre-rounding value). Finance requires
 * the rounding to be treated as a consequence of the user's change, so this class keeps a
 * transaction-scoped Set of Opportunity Ids that have already been logged and never logs the same
 * Opportunity twice in one transaction. Opportunities whose Amount did not change produce no Task.
 *
 * Bulk safety: records are filtered in a single loop and all Tasks are inserted with one DML
 * statement per trigger execution, supporting 200 records per update.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    @TestVisible
    private static final String TASK_SUBJECT = 'Amount changed';

    @TestVisible
    private static final String TASK_STATUS = 'Completed';

    /**
     * Opportunity Ids already logged in this transaction. Static, so it survives across the
     * recursive trigger runs caused by the rounding action, but is scoped to the transaction.
     */
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    /**
     * Allows tests (and only tests) to reset transaction-scoped state between test methods,
     * since static state persists for the duration of an entire test transaction.
     */
    @TestVisible
    private static void resetLoggedOpportunityIds() {
        loggedOpportunityIds = new Set<Id>();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Opportunity> newOpps = (List<Opportunity>) triggerNew;
        List<Opportunity> oldOpps = (List<Opportunity>) triggerOld;

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newOpps.size(); i++) {
            Opportunity newOpp = newOpps[i];
            Opportunity oldOpp = oldOpps[i];

            // At most one audit Task per Opportunity per transaction: skip any Opportunity
            // this action has already logged (e.g. on the recursive run caused by rounding).
            if (loggedOpportunityIds.contains(newOpp.Id)) {
                continue;
            }

            if (hasAmountChanged(newOpp, oldOpp)) {
                tasksToInsert.add(new Task(
                    Subject = TASK_SUBJECT,
                    Status = TASK_STATUS,
                    WhatId = newOpp.Id
                ));
                loggedOpportunityIds.add(newOpp.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }

    /**
     * Returns true when the Amount was modified, treating null <-> value transitions as changes
     * and treating Decimals with different scales but equal value (e.g. 10.50 vs 10.5) as equal.
     */
    private static Boolean hasAmountChanged(Opportunity newOpp, Opportunity oldOpp) {
        Decimal newAmount = newOpp.Amount;
        Decimal oldAmount = oldOpp.Amount;
        if (newAmount == null && oldAmount == null) {
            return false;
        }
        if (newAmount == null || oldAmount == null) {
            return true;
        }
        return newAmount.compareTo(oldAmount) != 0;
    }
}
