/**
 * Singleton query provider for the Contact before-insert trigger actions.
 *
 * TAF recommended pattern for avoiding repeated SOQL: a single trigger action
 * (the inner `Service` class) loads the parent Accounts exactly once per
 * trigger execution into `accountsById`. All other actions that need the
 * parent Account read it from `TA_Contact_Queries.getInstance()`.
 *
 * The map is reloaded on every trigger execution (rather than cached for the
 * whole transaction) because later DML in the same transaction can involve
 * other Accounts, so stale data must not be reused.
 */
public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    /** Parent Accounts for the current trigger execution, keyed by Id.
     *  Accounts that no longer exist (or were not referenced) are absent. */
    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    private void loadAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>();
            return;
        }
        accountsById = new Map<Id, Account>([
            SELECT
                AccountSource,
                BillingStreet,
                BillingCity,
                BillingPostalCode,
                BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    /**
     * Trigger action that runs first in before insert (Order__c = 1) and
     * populates the singleton's `accountsById` map for this execution.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject row : triggerNew) {
                Id accountId = (Id) row.get('AccountId');
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }
            TA_Contact_Queries.getInstance().loadAccounts(accountIds);
        }
    }
}
