/**
 * Contact before-insert action (Order__c = 20).
 *
 * When a new Contact has an Account and a blank LeadSource, defaults the
 * LeadSource to the Account's AccountSource. Contacts without an Account, or
 * with a LeadSource already populated, are left alone.
 *
 * Reads the parent Accounts from the TA_Contact_Queries singleton so that no
 * additional SOQL is issued in this action.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }
        for (SObject row : triggerNew) {
            Contact contact = (Contact) row;
            if (contact.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(contact.LeadSource)
                    && String.isNotBlank(account.AccountSource)) {
                contact.LeadSource = account.AccountSource;
            }
        }
    }
}
